{
  "name": "نظام تسجيل التربية العملية - كلية التربية بتفهنا الأشراف",
  "description": "منصة إلكترونية لتسجيل طلاب الفرقتين الثالثة والرابعة بكلية التربية بنين بتفهنا الأشراف في مجموعات التربية العملية بالمعاهد الأزهرية، مع ميزة استخراج خطابات التوجيه الرسمية."
}

export type Year = 'third' | 'fourth';

export interface Department {
  id: string;
  name: string;
}

export interface Student {
  id: string;
  name: string;
  nationalId: string;
  year: Year;
  departmentId: string;
  instituteId: string;
}

export interface Institute {
  id: string;
  name: string;
  location: string;
  maxCapacity: number;
  currentCount: number;
  departmentId: string;
  year: Year;
}

export interface User {
  username: string;
  role: 'admin' | 'student';
}

import { Department, Institute } from './types';

export const DEPARTMENTS: Department[] = [
  { id: 'islamic', name: 'دراسات إسلامية' },
  { id: 'arabic', name: 'لغة عربية' },
  { id: 'english', name: 'لغة إنجليزية' },
  { id: 'french', name: 'لغة فرنسية' },
  { id: 'history', name: 'تاريخ' },
  { id: 'geography', name: 'جغرافيا' },
  { id: 'tech', name: 'تكنولوجيا التعليم' },
  { id: 'psychology', name: 'علم نفس' },
  { id: 'special', name: 'تربية خاصة' },
  { id: 'social_basic', name: 'دراسات اجتماعية (تعليم أساسي)' },
  { id: 'arabic_basic', name: 'لغة عربية (تعليم أساسي)' },
];

// Generating some dummy institutes for demonstration
const generateInstitutes = (): Institute[] => {
  const institutes: Institute[] = [];
  const locations = ['تفهنا الأشراف', 'ميت غمر', 'المنصورة', 'السنبلاوين', 'دكرنس'];

  ['third', 'fourth'].forEach((year) => {
    DEPARTMENTS.forEach((dept) => {
      locations.forEach((loc, index) => {
        institutes.push({
          id: `${year}-${dept.id}-${index}`,
          name: `معهد ${loc} الأزهري (${index + 1})`,
          location: loc,
          maxCapacity: 6,
          currentCount: Math.floor(Math.random() * 4), // Initial random fill for demo
          departmentId: dept.id,
          year: year as any,
        });
      });
    });
  });

  return institutes;
};

export const INITIAL_INSTITUTES = generateInstitutes();

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect } from 'react';
import { User, Institute, Student } from './types';
import LoginForm from './components/LoginForm';
import Dashboard from './components/Dashboard';
import { INITIAL_INSTITUTES } from './constants';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [institutes, setInstitutes] = useState<Institute[]>(INITIAL_INSTITUTES);
  const [students, setStudents] = useState<Student[]>([]);

  // Simulate persistent storage in local session for demo
  useEffect(() => {
    const savedUser = localStorage.getItem('user');
    if (savedUser) setUser(JSON.parse(savedUser));

    const savedInstitutes = localStorage.getItem('institutes');
    if (savedInstitutes) setInstitutes(JSON.parse(savedInstitutes));

    const savedStudents = localStorage.getItem('students');
    if (savedStudents) setStudents(JSON.parse(savedStudents));
  }, []);

  const handleLogin = (username: string) => {
    const newUser: User = { username, role: 'admin' };
    setUser(newUser);
    localStorage.setItem('user', JSON.stringify(newUser));
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('user');
  };

  const registerStudent = (student: Student) => {
    // Update Institute count
    const updatedInstitutes = institutes.map(inst => {
      if (inst.id === student.instituteId) {
        if (inst.currentCount >= inst.maxCapacity) {
          alert("عذراً، هذا المعهد قد اكتمل عدده (6 طلاب)");
          return inst;
        }
        return { ...inst, currentCount: inst.currentCount + 1 };
      }
      return inst;
    });

    // Save changes
    const newStudents = [...students, student];
    setStudents(newStudents);
    setInstitutes(updatedInstitutes);

    localStorage.setItem('students', JSON.stringify(newStudents));
    localStorage.setItem('institutes', JSON.stringify(updatedInstitutes));
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50">
      {!user ? (
        <LoginForm onLogin={handleLogin} />
      ) : (
        <Dashboard 
          user={user} 
          onLogout={handleLogout} 
          institutes={institutes}
          students={students}
          onRegister={registerStudent}
        />
      )}

      <footer className="bg-slate-800 text-white py-6 mt-auto text-center no-print">
        <p className="text-sm font-semibold mb-1">جامعة الأزهر - كلية التربية بنين بتفهنا الأشراف</p>
        <p className="text-xs opacity-75">© جميع الحقوق محفوظة باسم (قسم المناهج وطرق التدريس)</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState } from 'react';

interface LoginFormProps {
  onLogin: (username: string) => void;
}

const LoginForm: React.FC<LoginFormProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (username.trim() && password.trim()) {
      onLogin(username);
    } else {
      alert("يرجى إدخال اسم المستخدم وكلمة المرور");
    }
  };

  return (
    <div className="flex-1 flex items-center justify-center p-4">
      <div className="w-full max-w-md bg-white rounded-2xl shadow-xl overflow-hidden">
        <div className="bg-emerald-700 p-8 text-center text-white">
          <img src="https://picsum.photos/seed/alazhar/100/100" alt="Logo" className="w-20 h-20 mx-auto rounded-full border-4 border-emerald-600 mb-4" />
          <h1 className="text-2xl font-bold">بوابة تسجيل التربية العملية</h1>
          <p className="text-emerald-100 text-sm mt-2">كلية التربية بنين بتفهنا الأشراف</p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6">
          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-2">اسم المستخدم (رقم الجلوس / الرقم القومي)</label>
            <input 
              type="text" 
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              className="w-full px-4 py-3 rounded-lg border border-slate-200 focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none transition"
              placeholder="أدخل اسم المستخدم"
            />
          </div>

          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-2">كلمة المرور</label>
            <input 
              type="password" 
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-4 py-3 rounded-lg border border-slate-200 focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none transition"
              placeholder="••••••••"
            />
          </div>

          <button 
            type="submit"
            className="w-full bg-emerald-700 hover:bg-emerald-800 text-white font-bold py-3 rounded-lg transition transform active:scale-95 shadow-lg shadow-emerald-200"
          >
            دخول للنظام
          </button>

          <div className="text-center text-xs text-slate-400">
            يرجى مراجعة قسم شؤون الطلاب في حال فقدان بيانات الدخول
          </div>
        </form>
      </div>
    </div>
  );
};

export default LoginForm;

import React, { useState } from 'react';
import { User, Institute, Student, Year } from '../types';
import { DEPARTMENTS } from '../constants';
import { LogOut, GraduationCap, School, FileText, UserPlus, CheckCircle } from 'lucide-react';
import LetterGenerator from './LetterGenerator';

interface DashboardProps {
  user: User;
  onLogout: () => void;
  institutes: Institute[];
  students: Student[];
  onRegister: (student: Student) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, onLogout, institutes, students, onRegister }) => {
  const [activeYear, setActiveYear] = useState<Year>('third');
  const [selectedDeptId, setSelectedDeptId] = useState<string>(DEPARTMENTS[0].id);
  const [showLetter, setShowLetter] = useState(false);
  const [letterInstituteId, setLetterInstituteId] = useState<string | null>(null);

  const filteredInstitutes = institutes.filter(
    inst => inst.year === activeYear && inst.departmentId === selectedDeptId
  );

  const getStudentsForInstitute = (instId: string) => {
    return students.filter(s => s.instituteId === instId);
  };

  const handleRegisterClick = (inst: Institute) => {
    if (inst.currentCount >= 6) {
      alert("عذراً، المجموعة مكتملة");
      return;
    }
    const name = prompt("يرجى إدخال اسم الطالب:");
    const nationalId = prompt("يرجى إدخال الرقم القومي للطالب:");

    if (name && nationalId) {
      const newStudent: Student = {
        id: Math.random().toString(36).substr(2, 9),
        name,
        nationalId,
        year: activeYear,
        departmentId: selectedDeptId,
        instituteId: inst.id
      };
      onRegister(newStudent);
    }
  };

  const openLetter = (instId: string) => {
    setLetterInstituteId(instId);
    setShowLetter(true);
  };

  return (
    <div className="flex-1 container mx-auto px-4 py-8">
      {/* Header */}
      <header className="flex flex-col md:flex-row justify-between items-center mb-10 bg-white p-6 rounded-2xl shadow-sm no-print">
        <div className="flex items-center gap-4 mb-4 md:mb-0">
          <div className="bg-emerald-100 p-3 rounded-full text-emerald-700">
            <School size={32} />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-slate-800">منصة التربية العملية</h1>
            <p className="text-slate-500">أهلاً بك، {user.username}</p>
          </div>
        </div>

        <button 
          onClick={onLogout}
          className="flex items-center gap-2 text-rose-600 hover:bg-rose-50 px-4 py-2 rounded-lg transition border border-rose-100"
        >
          <LogOut size={18} />
          تسجيل الخروج
        </button>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* Sidebar Nav */}
        <aside className="lg:col-span-1 space-y-6 no-print">
          <div className="bg-white rounded-2xl shadow-sm p-4">
            <h2 className="text-sm font-bold text-slate-400 uppercase tracking-wider mb-4 px-2">اختيار الفرقة</h2>
            <div className="space-y-2">
              <button 
                onClick={() => setActiveYear('third')}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition ${activeYear === 'third' ? 'bg-emerald-700 text-white shadow-lg' : 'hover:bg-slate-100 text-slate-600'}`}
              >
                <GraduationCap size={20} />
                الفرقة الثالثة
              </button>
              <button 
                onClick={() => setActiveYear('fourth')}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition ${activeYear === 'fourth' ? 'bg-emerald-700 text-white shadow-lg' : 'hover:bg-slate-100 text-slate-600'}`}
              >
                <GraduationCap size={20} />
                الفرقة الرابعة
              </button>
            </div>
          </div>

          <div className="bg-white rounded-2xl shadow-sm p-4">
            <h2 className="text-sm font-bold text-slate-400 uppercase tracking-wider mb-4 px-2">قائمة الشعب</h2>
            <div className="max-h-[500px] overflow-y-auto space-y-1 pr-1 custom-scrollbar">
              {DEPARTMENTS.map(dept => (
                <button 
                  key={dept.id}
                  onClick={() => setSelectedDeptId(dept.id)}
                  className={`w-full text-right px-4 py-3 rounded-lg text-sm transition ${selectedDeptId === dept.id ? 'bg-emerald-50 text-emerald-700 font-bold border-r-4 border-emerald-700' : 'text-slate-600 hover:bg-slate-50'}`}
                >
                  {dept.name}
                </button>
              ))}
            </div>
          </div>
        </aside>

        {/* Main Content Area */}
        <main className="lg:col-span-3">
          <div className="bg-white rounded-2xl shadow-sm overflow-hidden no-print">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
              <div>
                <h3 className="text-xl font-bold text-slate-800">
                  {activeYear === 'third' ? 'الفرقة الثالثة' : 'الفرقة الرابعة'} - {DEPARTMENTS.find(d => d.id === selectedDeptId)?.name}
                </h3>
                <p className="text-slate-500 text-sm mt-1">المعاهد المتاحة للتسجيل (الحد الأقصى 6 طلاب لكل مجموعة)</p>
              </div>
            </div>

            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
              {filteredInstitutes.length > 0 ? (
                filteredInstitutes.map(inst => {
                  const isFull = inst.currentCount >= inst.maxCapacity;
                  return (
                    <div key={inst.id} className={`border rounded-2xl p-6 transition flex flex-col justify-between ${isFull ? 'bg-slate-50 border-slate-200' : 'bg-white border-emerald-100 hover:shadow-md'}`}>
                      <div>
                        <div className="flex justify-between items-start mb-4">
                          <h4 className="font-bold text-lg text-slate-800">{inst.name}</h4>
                          {isFull ? (
                            <span className="bg-rose-100 text-rose-700 text-xs px-2 py-1 rounded-full font-bold">مكتمل</span>
                          ) : (
                            <span className="bg-emerald-100 text-emerald-700 text-xs px-2 py-1 rounded-full font-bold">متاح</span>
                          )}
                        </div>

                        <div className="space-y-3 mb-6">
                          <div className="flex items-center gap-2 text-sm text-slate-500">
                            <School size={16} />
                            <span>الموقع: {inst.location}</span>
                          </div>
                          <div className="w-full bg-slate-100 h-2 rounded-full overflow-hidden">
                            <div 
                              className={`h-full transition-all duration-500 ${isFull ? 'bg-rose-500' : 'bg-emerald-500'}`}
                              style={{ width: `${(inst.currentCount / 6) * 100}%` }}
                            ></div>
                          </div>
                          <div className="flex justify-between text-xs font-bold">
                            <span className="text-slate-400">السعة: {inst.maxCapacity}</span>
                            <span className={isFull ? 'text-rose-600' : 'text-emerald-600'}>المسجلين: {inst.currentCount}</span>
                          </div>
                        </div>
                      </div>

                      <div className="flex gap-2 pt-4 border-t border-slate-50">
                        {!isFull && (
                          <button 
                            onClick={() => handleRegisterClick(inst)}
                            className="flex-1 flex items-center justify-center gap-2 bg-emerald-700 text-white py-2 rounded-lg text-sm font-bold hover:bg-emerald-800 transition"
                          >
                            <UserPlus size={16} />
                            تسجيل طالب
                          </button>
                        )}
                        <button 
                          onClick={() => openLetter(inst.id)}
                          className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-lg text-sm font-bold transition border ${inst.currentCount > 0 ? 'border-emerald-700 text-emerald-700 hover:bg-emerald-50' : 'border-slate-200 text-slate-300 cursor-not-allowed'}`}
                          disabled={inst.currentCount === 0}
                        >
                          <FileText size={16} />
                          استخراج خطاب
                        </button>
                      </div>
                    </div>
                  );
                })
              ) : (
                <div className="col-span-full py-20 text-center text-slate-400">
                  <School size={48} className="mx-auto mb-4 opacity-20" />
                  لا توجد معاهد مسجلة لهذه الشعبة حالياً
                </div>
              )}
            </div>
          </div>
        </main>
      </div>

      {/* Letter Modal */}
      {showLetter && letterInstituteId && (
        <LetterGenerator 
          institute={institutes.find(i => i.id === letterInstituteId)!}
          students={getStudentsForInstitute(letterInstituteId)}
          onClose={() => setShowLetter(false)}
        />
      )}
    </div>
  );
};

export default Dashboard;

