import React, { useState } from 'react';
import { User, Institute, Student, Year } from '../types';
import { DEPARTMENTS } from '../constants';
import { LogOut, GraduationCap, School, FileText, UserPlus, Info, Users } from 'lucide-react';
import LetterGenerator from './LetterGenerator';

interface DashboardProps {
  user: User;
  onLogout: () => void;
  institutes: Institute[];
  students: Student[];
  onRegister: (student: Student) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, onLogout, institutes, students, onRegister }) => {
  const [activeYear, setActiveYear] = useState<Year>('third');
  const [selectedDeptId, setSelectedDeptId] = useState<string>(DEPARTMENTS[0].id);
  const [showLetter, setShowLetter] = useState(false);
  const [letterInstituteId, setLetterInstituteId] = useState<string | null>(null);

  const filteredInstitutes = institutes.filter(
    inst => inst.year === activeYear && inst.departmentId === selectedDeptId
  );

  const getStudentsForInstitute = (instId: string) => {
    return students.filter(s => s.instituteId === instId);
  };

  const handleRegisterClick = (inst: Institute) => {
    if (inst.currentCount >= 6) {
      alert("عذراً، المجموعة مكتملة");
      return;
    }
    const name = prompt("يرجى إدخال اسم الطالب:");
    const nationalId = prompt("يرجى إدخال الرقم القومي للطالب:");

    if (name && nationalId) {
      const newStudent: Student = {
        id: Math.random().toString(36).substr(2, 9),
        name,
        nationalId,
        year: activeYear,
        departmentId: selectedDeptId,
        instituteId: inst.id
      };
      onRegister(newStudent);
    }
  };

  const showStudentDetails = (student: Student) => {
    alert(`تفاصيل الطالب:\n\nالاسم: ${student.name}\nالرقم القومي: ${student.nationalId}\nالفرقة: ${student.year === 'third' ? 'الثالثة' : 'الرابعة'}`);
  };

  const openLetter = (instId: string) => {
    setLetterInstituteId(instId);
    setShowLetter(true);
  };

  return (
    <div className="flex-1 container mx-auto px-4 py-8">
      {/* Header */}
      <header className="flex flex-col md:flex-row justify-between items-center mb-10 bg-white p-6 rounded-2xl shadow-sm no-print">
        <div className="flex items-center gap-4 mb-4 md:mb-0">
          <div className="bg-emerald-100 p-3 rounded-full text-emerald-700">
            <School size={32} />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-slate-800">منصة التربية العملية</h1>
            <p className="text-slate-500">أهلاً بك، {user.username}</p>
          </div>
        </div>

        <button 
          onClick={onLogout}
          className="flex items-center gap-2 text-rose-600 hover:bg-rose-50 px-4 py-2 rounded-lg transition border border-rose-100"
        >
          <LogOut size={18} />
          تسجيل الخروج
        </button>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* Sidebar Nav */}
        <aside className="lg:col-span-1 space-y-6 no-print">
          <div className="bg-white rounded-2xl shadow-sm p-4">
            <h2 className="text-sm font-bold text-slate-400 uppercase tracking-wider mb-4 px-2">اختيار الفرقة</h2>
            <div className="space-y-2">
              <button 
                onClick={() => setActiveYear('third')}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition ${activeYear === 'third' ? 'bg-emerald-700 text-white shadow-lg' : 'hover:bg-slate-100 text-slate-600'}`}
              >
                <GraduationCap size={20} />
                الفرقة الثالثة
              </button>
              <button 
                onClick={() => setActiveYear('fourth')}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition ${activeYear === 'fourth' ? 'bg-emerald-700 text-white shadow-lg' : 'hover:bg-slate-100 text-slate-600'}`}
              >
                <GraduationCap size={20} />
                الفرقة الرابعة
              </button>
            </div>
          </div>

          <div className="bg-white rounded-2xl shadow-sm p-4">
            <h2 className="text-sm font-bold text-slate-400 uppercase tracking-wider mb-4 px-2">قائمة الشعب</h2>
            <div className="max-h-[500px] overflow-y-auto space-y-1 pr-1 custom-scrollbar">
              {DEPARTMENTS.map(dept => (
                <button 
                  key={dept.id}
                  onClick={() => setSelectedDeptId(dept.id)}
                  className={`w-full text-right px-4 py-3 rounded-lg text-sm transition ${selectedDeptId === dept.id ? 'bg-emerald-50 text-emerald-700 font-bold border-r-4 border-emerald-700' : 'text-slate-600 hover:bg-slate-50'}`}
                >
                  {dept.name}
                </button>
              ))}
            </div>
          </div>
        </aside>

        {/* Main Content Area */}
        <main className="lg:col-span-3">
          <div className="bg-white rounded-2xl shadow-sm overflow-hidden no-print">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
              <div>
                <h3 className="text-xl font-bold text-slate-800">
                  {activeYear === 'third' ? 'الفرقة الثالثة' : 'الفرقة الرابعة'} - {DEPARTMENTS.find(d => d.id === selectedDeptId)?.name}
                </h3>
                <p className="text-slate-500 text-sm mt-1">المعاهد المتاحة للتسجيل (الحد الأقصى 6 طلاب لكل مجموعة)</p>
              </div>
            </div>

            <div className="p-6 grid grid-cols-1 xl:grid-cols-2 gap-6">
              {filteredInstitutes.length > 0 ? (
                filteredInstitutes.map(inst => {
                  const isFull = inst.currentCount >= inst.maxCapacity;
                  const instStudents = getStudentsForInstitute(inst.id);
                  return (
                    <div key={inst.id} className={`border rounded-2xl p-6 transition flex flex-col ${isFull ? 'bg-slate-50 border-slate-200' : 'bg-white border-emerald-100 hover:shadow-md'}`}>
                      <div className="flex-1">
                        <div className="flex justify-between items-start mb-4">
                          <h4 className="font-bold text-lg text-slate-800">{inst.name}</h4>
                          {isFull ? (
                            <span className="bg-rose-100 text-rose-700 text-xs px-2 py-1 rounded-full font-bold">مكتمل</span>
                          ) : (
                            <span className="bg-emerald-100 text-emerald-700 text-xs px-2 py-1 rounded-full font-bold">متاح</span>
                          )}
                        </div>

                        <div className="space-y-3 mb-6">
                          <div className="flex items-center gap-2 text-sm text-slate-500">
                            <School size={16} />
                            <span>الموقع: {inst.location}</span>
                          </div>
                          <div className="w-full bg-slate-100 h-2 rounded-full overflow-hidden">
                            <div 
                              className={`h-full transition-all duration-500 ${isFull ? 'bg-rose-500' : 'bg-emerald-500'}`}
                              style={{ width: `${(inst.currentCount / 6) * 100}%` }}
                            ></div>
                          </div>
                          <div className="flex justify-between text-xs font-bold">
                            <span className="text-slate-400">السعة: {inst.maxCapacity}</span>
                            <span className={isFull ? 'text-rose-600' : 'text-emerald-600'}>المسجلين: {inst.currentCount}</span>
                          </div>
                        </div>

                        {/* Registered Students Column/List */}
                        <div className="bg-slate-50 rounded-xl p-3 mb-6">
                          <h5 className="text-xs font-bold text-slate-400 uppercase mb-3 flex items-center gap-1">
                            <Users size={14} />
                            الطلاب المسجلون:
                          </h5>
                          {instStudents.length > 0 ? (
                            <ul className="space-y-2">
                              {instStudents.map((student, idx) => (
                                <li 
                                  key={student.id} 
                                  onClick={() => showStudentDetails(student)}
                                  className="flex items-center justify-between text-sm bg-white p-2 rounded-lg border border-slate-100 hover:border-emerald-300 hover:shadow-sm transition cursor-pointer group"
                                >
                                  <span className="font-semibold text-slate-700 group-hover:text-emerald-700">
                                    {idx + 1}. {student.name}
                                  </span>
                                  <Info size={14} className="text-slate-300 group-hover:text-emerald-500" />
                                </li>
                              ))}
                            </ul>
                          ) : (
                            <p className="text-xs text-slate-400 italic text-center py-2">لا يوجد طلاب مسجلون حتى الآن</p>
                          )}
                        </div>
                      </div>

                      <div className="flex gap-2 pt-4 border-t border-slate-100">
                        {!isFull && (
                          <button 
                            onClick={() => handleRegisterClick(inst)}
                            className="flex-1 flex items-center justify-center gap-2 bg-emerald-700 text-white py-2 rounded-lg text-sm font-bold hover:bg-emerald-800 transition shadow-sm"
                          >
                            <UserPlus size={16} />
                            تسجيل طالب
                          </button>
                        )}
                        <button 
                          onClick={() => openLetter(inst.id)}
                          className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-lg text-sm font-bold transition border ${inst.currentCount > 0 ? 'border-emerald-700 text-emerald-700 hover:bg-emerald-50' : 'border-slate-200 text-slate-300 cursor-not-allowed'}`}
                          disabled={inst.currentCount === 0}
                        >
                          <FileText size={16} />
                          استخراج خطاب
                        </button>
                      </div>
                    </div>
                  );
                })
              ) : (
                <div className="col-span-full py-20 text-center text-slate-400">
                  <School size={48} className="mx-auto mb-4 opacity-20" />
                  لا توجد معاهد مسجلة لهذه الشعبة حالياً
                </div>
              )}
            </div>
          </div>
        </main>
      </div>

      {/* Letter Modal */}
      {showLetter && letterInstituteId && (
        <LetterGenerator 
          institute={institutes.find(i => i.id === letterInstituteId)!}
          students={getStudentsForInstitute(letterInstituteId)}
          onClose={() => setShowLetter(false)}
        />
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { User, Institute, Student, Year } from '../types';
import { DEPARTMENTS } from '../constants';
