            </div>
          </div>
        </aside>

        {/* Main Content Area */}
        <main className="lg:col-span-3">
          <div className="bg-white rounded-2xl shadow-sm overflow-hidden no-print">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
              <div>
                <h3 className="text-xl font-bold text-slate-800">
                  {activeYear === 'third' ? 'الفرقة الثالثة' : 'الفرقة الرابعة'} - {DEPARTMENTS.find(d => d.id === selectedDeptId)?.name}
                </h3>
                <p className="text-slate-500 text-sm mt-1">المعاهد المتاحة للتسجيل (الحد الأقصى 6 طلاب لكل مجموعة)</p>
              </div>
            </div>

            <div className="p-6 grid grid-cols-1 xl:grid-cols-2 gap-6">
              {filteredInstitutes.length > 0 ? (
                filteredInstitutes.map(inst => {
                  const isFull = inst.currentCount >= inst.maxCapacity;
                  const instStudents = getStudentsForInstitute(inst.id);
                  return (
                    <div key={inst.id} className={`border rounded-2xl p-6 transition flex flex-col ${isFull ? 'bg-slate-50 border-slate-200' : 'bg-white border-emerald-100 hover:shadow-md'}`}>
                      <div className="flex-1">
                        <div className="flex justify-between items-start mb-4">
                          <h4 className="font-bold text-lg text-slate-800">{inst.name}</h4>
                          {isFull ? (
                            <span className="bg-rose-100 text-rose-700 text-xs px-2 py-1 rounded-full font-bold">مكتمل</span>
                          ) : (
                            <span className="bg-emerald-100 text-emerald-700 text-xs px-2 py-1 rounded-full font-bold">متاح</span>
                          )}
                        </div>

                        <div className="space-y-3 mb-6">
                          <div className="flex items-center gap-2 text-sm text-slate-500">
                            <School size={16} />
                            <span>الموقع: {inst.location}</span>
                          </div>
                          <div className="w-full bg-slate-100 h-2 rounded-full overflow-hidden">
                            <div 
                              className={`h-full transition-all duration-500 ${isFull ? 'bg-rose-500' : 'bg-emerald-500'}`}
                              style={{ width: `${(inst.currentCount / 6) * 100}%` }}
                            ></div>
                          </div>
                          <div className="flex justify-between text-xs font-bold">
                            <span className="text-slate-400">السعة: {inst.maxCapacity}</span>
                            <span className={isFull ? 'text-rose-600' : 'text-emerald-600'}>المسجلين: {inst.currentCount}</span>
                          </div>
                        </div>

                        {/* Registered Students Column/List */}
                        <div className="bg-slate-50 rounded-xl p-3 mb-6">
                          <h5 className="text-xs font-bold text-slate-400 uppercase mb-3 flex items-center gap-1">
                            <Users size={14} />
                            الطلاب المسجلون:
                          </h5>
                          {instStudents.length > 0 ? (
                            <ul className="space-y-2">
                              {instStudents.map((student, idx) => (
                                <li 
                                  key={student.id} 
                                  onClick={() => showStudentDetails(student)}
                                  className="flex items-center justify-between text-sm bg-white p-2 rounded-lg border border-slate-100 hover:border-emerald-300 hover:shadow-sm transition cursor-pointer group"
