                                  <span className="font-semibold text-slate-700 group-hover:text-emerald-700">
                                    {idx + 1}. {student.name}
                                  </span>
                                  <Info size={14} className="text-slate-300 group-hover:text-emerald-500" />
                                </li>
                              ))}
                            </ul>
                          ) : (
