                            تسجيل طالب
                          </button>
                        )}
                        <button 
                          onClick={() => openLetter(inst.id)}
                          className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-lg text-sm font-bold transition border ${inst.currentCount > 0 ? 'border-emerald-700 text-emerald-700 hover:bg-emerald-50' : 'border-slate-200 text-slate-300 cursor-not-allowed'}`}
                          disabled={inst.currentCount === 0}
                        >
                          <FileText size={16} />
                          استخراج خطاب
