                                  <span className={`font-semibold ${isFull ? 'text-rose-900 group-hover:text-rose-700' : 'text-slate-700 group-hover:text-emerald-700'}`}>
                                    {idx + 1}. {student.name}
                                  </span>
                                  <Info size={14} className={`${isFull ? 'text-rose-200 group-hover:text-rose-400' : 'text-slate-300 group-hover:text-emerald-500'}`} />
                                </li>
                              ))}
                            </ul>
                          ) : (
                            <p className="text-xs text-slate-400 italic text-center py-2">لا يوجد طلاب مسجلون حتى الآن</p>
                          )}
                        </div>
                      </div>

                      <div className={`flex gap-2 pt-4 border-t ${isFull ? 'border-rose-200' : 'border-slate-100'}`}>
                        {!isFull && (
                          <button 
                            onClick={() => handleRegisterClick(inst)}
                            className="flex-1 flex items-center justify-center gap-2 bg-emerald-700 text-white py-2 rounded-lg text-sm font-bold hover:bg-emerald-800 transition shadow-sm"
                          >
                            <UserPlus size={16} />
                            تسجيل طالب
                          </button>
                        )}
                        <button 
                          onClick={() => openLetter(inst.id)}
                          className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-lg text-sm font-bold transition border ${inst.currentCount > 0 ? (isFull ? 'border-rose-600 text-rose-600 hover:bg-rose-50' : 'border-emerald-700 text-emerald-700 hover:bg-emerald-50') : 'border-slate-200 text-slate-300 cursor-not-allowed'}`}
                          disabled={inst.currentCount === 0}
                        >
                          <FileText size={16} />
                          استخراج خطاب
                        </button>
                      </div>
                    </div>
                  );
                })
              ) : (
                <div className="col-span-full py-20 text-center text-slate-400">
                  <School size={48} className="mx-auto mb-4 opacity-20" />
                  لا توجد معاهد مسجلة لهذه الشعبة حالياً
                </div>
              )}
            </div>
          </div>
        </main>
      </div>

      {/* Student Details Modal */}
      {selectedStudent && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/60 p-4 backdrop-blur-sm">
          <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
            <div className="bg-slate-50 p-6 border-b flex justify-between items-center">
              <h3 className="font-bold text-slate-800 flex items-center gap-2">
                <Users size={20} className="text-emerald-700" />
                بيانات الطالب المسجل
              </h3>
              <button onClick={() => setSelectedStudent(null)} className="p-1 hover:bg-slate-200 rounded-full transition">
                <X size={20} />
              </button>
            </div>
            <div className="p-8 space-y-6">
              <div className="space-y-4">
                <div className="flex flex-col gap-1">
                  <span className="text-xs font-bold text-slate-400 uppercase">الاسم الكامل</span>
                  <span className="text-lg font-bold text-slate-800">{selectedStudent.name}</span>
                </div>
                <div className="flex flex-col gap-1">
                  <span className="text-xs font-bold text-slate-400 uppercase">الرقم القومي</span>
                  <span className="text-lg font-bold text-slate-600 font-mono tracking-wider">{selectedStudent.nationalId}</span>
                </div>
                <div className="flex flex-col gap-1">
                  <span className="text-xs font-bold text-slate-400 uppercase">المعهد</span>
                  <span className="text-md font-semibold text-emerald-700">
                    {institutes.find(i => i.id === selectedStudent.instituteId)?.name}
                  </span>
                </div>
              </div>

              <div className="pt-6 border-t border-slate-100">
                <button 
                  onClick={() => handleRemoveClick(selectedStudent)}
                  className="w-full flex items-center justify-center gap-2 bg-rose-50 text-rose-600 hover:bg-rose-600 hover:text-white py-3 rounded-xl font-bold transition-all border border-rose-100"
                >
                  <Trash2 size={18} />
                  تعديل / حذف السجل
                </button>
                <p className="text-[10px] text-slate-400 text-center mt-3">
                  * يتطلب إجراء تعديلات على السجل موافقة تأكيدية مزدوجة.
                </p>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Letter Modal */}
      {showLetter && letterInstituteId && (
        <LetterGenerator 
          institute={institutes.find(i => i.id === letterInstituteId)!}
          students={getStudentsForInstitute(letterInstituteId)}
          onClose={() => setShowLetter(false)}
        />
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { User, Institute, Student } from './types';
import LoginForm from './components/LoginForm';
import Dashboard from './components/Dashboard';
import { INITIAL_INSTITUTES } from './constants';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [institutes, setInstitutes] = useState<Institute[]>(INITIAL_INSTITUTES);
  const [students, setStudents] = useState<Student[]>([]);

  // Simulate persistent storage in local session for demo
  useEffect(() => {
    const savedUser = localStorage.getItem('user');
    if (savedUser) setUser(JSON.parse(savedUser));

    const savedInstitutes = localStorage.getItem('institutes');
    if (savedInstitutes) setInstitutes(JSON.parse(savedInstitutes));

    const savedStudents = localStorage.getItem('students');
    if (savedStudents) setStudents(JSON.parse(savedStudents));
  }, []);

  const handleLogin = (username: string) => {
    const newUser: User = { username, role: 'admin' };
    setUser(newUser);
    localStorage.setItem('user', JSON.stringify(newUser));
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('user');
  };

  const registerStudent = (student: Student) => {
    const updatedInstitutes = institutes.map(inst => {
      if (inst.id === student.instituteId) {
        if (inst.currentCount >= inst.maxCapacity) {
          alert("عذراً، هذا المعهد قد اكتمل عدده (6 طلاب)");
          return inst;
        }
        return { ...inst, currentCount: inst.currentCount + 1 };
      }
      return inst;
    });

    const newStudents = [...students, student];
    setStudents(newStudents);
    setInstitutes(updatedInstitutes);

    localStorage.setItem('students', JSON.stringify(newStudents));
    localStorage.setItem('institutes', JSON.stringify(updatedInstitutes));
  };

  const removeStudent = (studentId: string, instituteId: string) => {
    const updatedStudents = students.filter(s => s.id !== studentId);
    const updatedInstitutes = institutes.map(inst => 
      inst.id === instituteId 
        ? { ...inst, currentCount: Math.max(0, inst.currentCount - 1) }
        : inst
    );

    setStudents(updatedStudents);
    setInstitutes(updatedInstitutes);

    localStorage.setItem('students', JSON.stringify(updatedStudents));
    localStorage.setItem('institutes', JSON.stringify(updatedInstitutes));
  };

  // Institute Management Functions
  const addInstitute = (newInst: Omit<Institute, 'id' | 'currentCount'>) => {
    const id = `${newInst.year}-${newInst.departmentId}-${Date.now()}`;
    const institute: Institute = { ...newInst, id, currentCount: 0 };
    const updated = [institute, ...institutes];
    setInstitutes(updated);
    localStorage.setItem('institutes', JSON.stringify(updated));
  };

  const updateInstitute = (id: string, newName: string) => {
    const updated = institutes.map(inst => inst.id === id ? { ...inst, name: newName } : inst);
    setInstitutes(updated);
    localStorage.setItem('institutes', JSON.stringify(updated));
  };

  const deleteInstitute = (id: string) => {
    // Check if there are students registered
    const studentsInInst = students.filter(s => s.instituteId === id);
    if (studentsInInst.length > 0) {
      const confirmDelete = window.confirm(`هذا المعهد يحتوي على ${studentsInInst.length} طلاب مسجلين. هل أنت متأكد من حذفه وحذف سجلات الطلاب التابعة له؟`);
      if (!confirmDelete) return;

      const remainingStudents = students.filter(s => s.instituteId !== id);
      setStudents(remainingStudents);
      localStorage.setItem('students', JSON.stringify(remainingStudents));
    }

    const updated = institutes.filter(inst => inst.id !== id);
    setInstitutes(updated);
    localStorage.setItem('institutes', JSON.stringify(updated));
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50">
      {!user ? (
        <LoginForm onLogin={handleLogin} />
      ) : (
        <Dashboard 
          user={user} 
          onLogout={handleLogout} 
          institutes={institutes}
          students={students}
          onRegister={registerStudent}
          onRemoveStudent={removeStudent}
          onAddInstitute={addInstitute}
          onUpdateInstitute={updateInstitute}
          onDeleteInstitute={deleteInstitute}
        />
      )}

      <footer className="bg-slate-800 text-white py-6 mt-auto text-center no-print">
        <p className="text-sm font-semibold mb-1">جامعة الأزهر - كلية التربية بنين بتفهنا الأشراف</p>
        <p className="text-xs opacity-75">© جميع الحقوق محفوظة باسم (قسم المناهج وطرق التدريس)</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { User, Institute, Student, Year } from '../types';
import { DEPARTMENTS } from '../constants';
import { LogOut, GraduationCap, School, FileText, UserPlus, Info, Users, Lock, Trash2, X, Edit2, PlusCircle } from 'lucide-react';
import LetterGenerator from './LetterGenerator';

interface DashboardProps {
  user: User;
  onLogout: () => void;
  institutes: Institute[];
  students: Student[];
  onRegister: (student: Student) => void;
  onRemoveStudent: (studentId: string, instituteId: string) => void;
  onAddInstitute: (newInst: Omit<Institute, 'id' | 'currentCount'>) => void;
  onUpdateInstitute: (id: string, newName: string) => void;
  onDeleteInstitute: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ 
  user, onLogout, institutes, students, onRegister, onRemoveStudent, 
  onAddInstitute, onUpdateInstitute, onDeleteInstitute 
}) => {
  const [activeYear, setActiveYear] = useState<Year>('third');
  const [selectedDeptId, setSelectedDeptId] = useState<string>(DEPARTMENTS[0].id);
  const [showLetter, setShowLetter] = useState(false);
  const [letterInstituteId, setLetterInstituteId] = useState<string | null>(null);
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);

  const filteredInstitutes = institutes.filter(
    inst => inst.year === activeYear && inst.departmentId === selectedDeptId
  );

  const getStudentsForInstitute = (instId: string) => {
    return students.filter(s => s.instituteId === instId);
  };

  const handleRegisterClick = (inst: Institute) => {
    if (inst.currentCount >= 6) {
      alert("عذراً، المجموعة مكتملة");
      return;
    }

    const isConfirmed = window.confirm(`هل أنت متأكد من رغبتك في التسجيل بمعهد: (${inst.name})؟\nيرجى العلم أنه لا يمكن تعديل الرغبة بعد الحفظ.`);

    if (!isConfirmed) return;

    const name = prompt("يرجى إدخال اسم الطالب كاملاً:");
    if (name === null) return;

    const nationalId = prompt("يرجى إدخال الرقم القومي للطالب (14 رقم):");
    if (nationalId === null) return;

    if (name.trim() && nationalId.trim()) {
      if (nationalId.length !== 14 || isNaN(Number(nationalId))) {
        alert("خطأ: الرقم القومي يجب أن يتكون من 14 رقماً");
        return;
      }

      const newStudent: Student = {
        id: Math.random().toString(36).substr(2, 9),
        name: name.trim(),
        nationalId: nationalId.trim(),
        year: activeYear,
        departmentId: selectedDeptId,
        instituteId: inst.id
      };
      onRegister(newStudent);
      alert("تم تسجيل الطالب بنجاح في المجموعة.");
    } else {
      alert("خطأ: يرجى ملء كافة البيانات المطلوبة");
    }
  };

  const handleRemoveClick = (student: Student) => {
    const firstConfirm = window.confirm(`هل تود إجراء تعديل على سجل الطالب: ${student.name}؟ (سيتم حذف السجل لإعادة التسجيل)`);
    if (firstConfirm) {
      const secondConfirm = window.confirm("تنبيه نهائي: هل أنت متأكد من حذف هذا السجل؟ سيتم إخلاء مكان الطالب في المجموعة ولا يمكن التراجع.");
      if (secondConfirm) {
        onRemoveStudent(student.id, student.instituteId);
        setSelectedStudent(null);
        alert("تم حذف سجل الطالب بنجاح.");
      }
    }
  };

  const handleAddInst = () => {
    const name = prompt("أدخل اسم المعهد الجديد:");
    if (!name) return;
    const location = prompt("أدخل موقع المعهد (المدينة/القرية):");
    if (!location) return;

    onAddInstitute({
      name,
      location,
      maxCapacity: 6,
      departmentId: selectedDeptId,
      year: activeYear
    });
    alert("تم إضافة المعهد بنجاح.");
  };

  const handleEditInst = (inst: Institute) => {
    const newName = prompt("تعديل اسم المعهد:", inst.name);
    if (newName && newName !== inst.name) {
      onUpdateInstitute(inst.id, newName);
    }
  };

  const handleDeleteInst = (id: string) => {
    if (window.confirm("هل أنت متأكد تماماً من رغبتك في حذف هذا المعهد نهائياً من النظام؟")) {
      onDeleteInstitute(id);
    }
  };

  const openLetter = (instId: string) => {
    setLetterInstituteId(instId);
    setShowLetter(true);
  };

  return (
    <div className="flex-1 container mx-auto px-4 py-8">
      {/* Header */}
      <header className="flex flex-col md:flex-row justify-between items-center mb-10 bg-white p-6 rounded-2xl shadow-sm no-print">
        <div className="flex items-center gap-4 mb-4 md:mb-0">
          <div className="bg-emerald-100 p-3 rounded-full text-emerald-700">
            <School size={32} />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-slate-800">منصة التربية العملية</h1>
            <p className="text-slate-500">أهلاً بك، {user.username}</p>
          </div>
        </div>

        <button 
          onClick={onLogout}
          className="flex items-center gap-2 text-rose-600 hover:bg-rose-50 px-4 py-2 rounded-lg transition border border-rose-100"
        >
          <LogOut size={18} />
          تسجيل الخروج
        </button>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* Sidebar Nav */}
        <aside className="lg:col-span-1 space-y-6 no-print">
          <div className="bg-white rounded-2xl shadow-sm p-4">
            <h2 className="text-sm font-bold text-slate-400 uppercase tracking-wider mb-4 px-2">اختيار الفرقة</h2>
            <div className="space-y-2">
              <button 
                onClick={() => setActiveYear('third')}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition ${activeYear === 'third' ? 'bg-emerald-700 text-white shadow-lg' : 'hover:bg-slate-100 text-slate-600'}`}
              >
                <GraduationCap size={20} />
                الفرقة الثالثة
              </button>
              <button 
                onClick={() => setActiveYear('fourth')}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition ${activeYear === 'fourth' ? 'bg-emerald-700 text-white shadow-lg' : 'hover:bg-slate-100 text-slate-600'}`}
              >
                <GraduationCap size={20} />
                الفرقة الرابعة
              </button>
            </div>
          </div>

          <div className="bg-white rounded-2xl shadow-sm p-4">
            <h2 className="text-sm font-bold text-slate-400 uppercase tracking-wider mb-4 px-2">قائمة الشعب</h2>
            <div className="max-h-[500px] overflow-y-auto space-y-1 pr-1 custom-scrollbar">
              {DEPARTMENTS.map(dept => (
                <button 
                  key={dept.id}
                  onClick={() => setSelectedDeptId(dept.id)}
                  className={`w-full text-right px-4 py-3 rounded-lg text-sm transition ${selectedDeptId === dept.id ? 'bg-emerald-50 text-emerald-700 font-bold border-r-4 border-emerald-700' : 'text-slate-600 hover:bg-slate-50'}`}
                >
                  {dept.name}
                </button>
              ))}
            </div>
          </div>
        </aside>

        {/* Main Content Area */}
        <main className="lg:col-span-3">
          <div className="bg-white rounded-2xl shadow-sm overflow-hidden no-print">
            <div className="p-6 border-b border-slate-100 flex flex-col sm:flex-row justify-between items-center bg-slate-50/50 gap-4">
              <div>
                <h3 className="text-xl font-bold text-slate-800">
                  {activeYear === 'third' ? 'الفرقة الثالثة' : 'الفرقة الرابعة'} - {DEPARTMENTS.find(d => d.id === selectedDeptId)?.name}
                </h3>
                <p className="text-slate-500 text-sm mt-1">إدارة المعاهد والمجموعات (6 طلاب بحد أقصى)</p>
