                        <div className="space-y-3 mb-6">
                          <div className="flex items-center gap-2 text-sm text-slate-500">
                            <School size={16} />
                            <span>الموقع: {inst.location}</span>
                          </div>
                          <div className="w-full bg-slate-100 h-2 rounded-full overflow-hidden">
                            <div 
                              className={`h-full transition-all duration-500 ${isFull ? 'bg-rose-600' : 'bg-emerald-500'}`}
                              style={{ width: `${(inst.currentCount / 6) * 100}%` }}
                            ></div>
                          </div>
                          <div className="flex justify-between text-xs font-bold">
                            <span className="text-slate-400">السعة: {inst.maxCapacity}</span>
                            <span className={isFull ? 'text-rose-700' : 'text-emerald-600'}>المسجلين: {inst.currentCount}</span>
                          </div>
                        </div>

                        {/* Registered Students Column/List */}
                        <div className={`${isFull ? 'bg-rose-100/50' : 'bg-slate-50'} rounded-xl p-3 mb-6`}>
                          <h5 className={`text-xs font-bold ${isFull ? 'text-rose-400' : 'text-slate-400'} uppercase mb-3 flex items-center gap-1`}>
                            <Users size={14} />
                            الطلاب المسجلون:
                          </h5>
                          {instStudents.length > 0 ? (
                            <ul className="space-y-2">
                              {instStudents.map((student, idx) => (
                                <li 
                                  key={student.id} 
                                  onClick={() => setSelectedStudent(student)}
                                  className={`flex items-center justify-between text-sm bg-white p-2 rounded-lg border transition cursor-pointer group ${isFull ? 'border-rose-100 hover:border-rose-300' : 'border-slate-100 hover:border-emerald-300 shadow-sm'}`}
                                >
                                  <span className={`font-semibold ${isFull ? 'text-rose-900 group-hover:text-rose-700' : 'text-slate-700 group-hover:text-emerald-700'}`}>
                                    {idx + 1}. {student.name}
                                  </span>
                                  <Info size={14} className={`${isFull ? 'text-rose-200 group-hover:text-rose-400' : 'text-slate-300 group-hover:text-emerald-500'}`} />
                                </li>
                              ))}
                            </ul>
                          ) : (
                            <p className="text-xs text-slate-400 italic text-center py-2">لا يوجد طلاب مسجلون حتى الآن</p>
                          )}
                        </div>
                      </div>

                      <div className={`flex gap-2 pt-4 border-t ${isFull ? 'border-rose-200' : 'border-slate-100'}`}>
                        {!isFull && (
                          <button 
                            onClick={() => handleRegisterClick(inst)}
                            className="flex-1 flex items-center justify-center gap-2 bg-emerald-700 text-white py-2 rounded-lg text-sm font-bold hover:bg-emerald-800 transition shadow-sm"
                          >
                            <UserPlus size={16} />
