                  <span className="text-lg font-bold text-slate-800">{selectedStudent.name}</span>
                </div>
                <div className="flex flex-col gap-1">
                  <span className="text-xs font-bold text-slate-400 uppercase">الرقم القومي</span>
                  <span className="text-lg font-bold text-slate-600 font-mono tracking-wider">{selectedStudent.nationalId}</span>
                </div>
                <div className="flex flex-col gap-1">
                  <span className="text-xs font-bold text-slate-400 uppercase">المعهد</span>
                  <span className="text-md font-semibold text-emerald-700">
                    {institutes.find(i => i.id === selectedStudent.instituteId)?.name}
                  </span>
                </div>
              </div>

              <div className="pt-6 border-t border-slate-100">
                <button 
                  onClick={() => handleRemoveClick(selectedStudent)}
                  className="w-full flex items-center justify-center gap-2 bg-rose-50 text-rose-600 hover:bg-rose-600 hover:text-white py-3 rounded-xl font-bold transition-all border border-rose-100"
