      alert("يرجى إدخال الاسم الرباعي والرقم القومي");
      return;
    }

    if (nationalId.length !== 16 || isNaN(Number(nationalId))) {
      alert("خطأ: يجب أن يتكون الرقم القومي من 16 رقماً كما هو مطلوب");
      return;
    }

    onLogin(username);
