            <label className="block text-sm font-semibold text-slate-700 mb-2">اسم المستخدم (الاسم رباعي)</label>
            <input 
              type="text" 
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              className="w-full px-4 py-3 rounded-lg border border-slate-200 focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none transition text-right"
              placeholder="أدخل الاسم الرباعي كاملاً"
              required
            />
