              type="text" 
              value={nationalId}
              maxLength={16}
              onChange={(e) => setNationalId(e.target.value.replace(/\D/g, ''))}
              className="w-full px-4 py-3 rounded-lg border border-slate-200 focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none transition text-center tracking-widest font-mono"
              placeholder="0000000000000000"
              required
            />
          </div>

          <button 
            type="submit"
            className="w-full bg-emerald-700 hover:bg-emerald-800 text-white font-bold py-3 rounded-lg transition transform active:scale-95 shadow-lg shadow-emerald-200"
          >
            دخول للنظام
          </button>

          <div className="text-center text-xs text-slate-400">
            ملاحظة: تأكد من كتابة الرقم القومي بدقة (16 رقم) لتسهيل استخراج الخطابات والتقارير.
          </div>
        </form>
      </div>
    </div>
  );
};

export default LoginForm;

import React, { useState } from 'react';
import { User, Institute, Student, Year } from '../types';
import { DEPARTMENTS } from '../constants';
import { LogOut, GraduationCap, School, FileText, UserPlus, Info, Users, Lock, Trash2, X, Edit2, PlusCircle, Download, Printer } from 'lucide-react';
import LetterGenerator from './LetterGenerator';

interface DashboardProps {
  user: User;
  onLogout: () => void;
  institutes: Institute[];
  students: Student[];
  onRegister: (student: Student) => void;
  onRemoveStudent: (studentId: string, instituteId: string) => void;
  onAddInstitute: (newInst: Omit<Institute, 'id' | 'currentCount'>) => void;
  onUpdateInstitute: (id: string, newName: string) => void;
  onDeleteInstitute: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ 
  user, onLogout, institutes, students, onRegister, onRemoveStudent, 
  onAddInstitute, onUpdateInstitute, onDeleteInstitute 
}) => {
  const [activeYear, setActiveYear] = useState<Year>('third');
  const [selectedDeptId, setSelectedDeptId] = useState<string>(DEPARTMENTS[0].id);
  const [showLetter, setShowLetter] = useState(false);
  const [letterInstituteId, setLetterInstituteId] = useState<string | null>(null);
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);
  const [showSectionReport, setShowSectionReport] = useState(false);

  const filteredInstitutes = institutes.filter(
    inst => inst.year === activeYear && inst.departmentId === selectedDeptId
  );

  const studentsInSection = students.filter(
    s => s.year === activeYear && s.departmentId === selectedDeptId
  ).sort((a, b) => a.name.localeCompare(b.name, 'ar'));

  const getStudentsForInstitute = (instId: string) => {
    return students.filter(s => s.instituteId === instId);
  };

  const handleRegisterClick = (inst: Institute) => {
    if (inst.currentCount >= 6) {
      alert("عذراً، المجموعة مكتملة");
      return;
    }

    const isConfirmed = window.confirm(`هل أنت متأكد من رغبتك في التسجيل بمعهد: (${inst.name})؟\nيرجى العلم أنه لا يمكن تعديل الرغبة بعد الحفظ.`);
    if (!isConfirmed) return;

    const name = prompt("يرجى إدخال اسم الطالب رباعياً:");
    if (name === null) return;

    const nationalId = prompt("يرجى إدخال الرقم القومي للطالب (16 رقم):");
    if (nationalId === null) return;

    if (name.trim() && nationalId.trim()) {
      if (nationalId.length !== 16 || isNaN(Number(nationalId))) {
        alert("خطأ: يجب أن يتكون الرقم القومي من 16 رقماً");
        return;
      }

      const newStudent: Student = {
        id: Math.random().toString(36).substr(2, 9),
        name: name.trim(),
        nationalId: nationalId.trim(),
        year: activeYear,
        departmentId: selectedDeptId,
        instituteId: inst.id
      };
      onRegister(newStudent);
      alert("تم تسجيل الطالب بنجاح.");
    } else {
      alert("خطأ: يرجى ملء كافة البيانات المطلوبة");
    }
  };

  const handleRemoveClick = (student: Student) => {
    const firstConfirm = window.confirm(`هل تود حذف سجل الطالب: ${student.name}؟`);
    if (firstConfirm) {
      const secondConfirm = window.confirm("تنبيه: سيتم إخلاء مكان الطالب في المجموعة. هل أنت متأكد؟");
