              onChange={(e) => setUsername(e.target.value)}
              className="w-full px-4 py-3 rounded-xl border-2 border-slate-100 focus:border-emerald-500 focus:ring-0 outline-none transition-all text-right text-slate-800 font-semibold"
              placeholder="مثال: محمد أحمد علي حسن"
              required
            />
          </div>

          <div className="space-y-1">
            <label className="block text-sm font-bold text-slate-700 mr-1">الرقم القومي (14 رقم)</label>
            <input 
              type="text" 
              value={nationalId}
              maxLength={14}
              onChange={(e) => setNationalId(e.target.value.replace(/\D/g, ''))}
              className="w-full px-4 py-3 rounded-xl border-2 border-slate-100 focus:border-emerald-500 focus:ring-0 outline-none transition-all text-center tracking-[0.2em] font-mono text-lg text-slate-700"
              placeholder="20000000000000"
              required
            />
          </div>

          <button 
            type="submit"
            className="w-full bg-emerald-700 hover:bg-emerald-800 text-white font-bold py-4 rounded-xl transition-all transform hover:-translate-y-1 active:scale-95 shadow-xl shadow-emerald-100 flex items-center justify-center gap-2"
          >
            تسجيل الدخول للنظام
          </button>

          <div className="bg-slate-50 p-4 rounded-lg text-center">
            <p className="text-[11px] text-slate-500 leading-relaxed">
              * يتم تخزين بياناتك لضمان سهولة اطلاع القسم على قوائم التوزيع واستخراج خطابات التوجيه.
            </p>
          </div>
        </form>
      </div>
    </div>
  );
};

