  const handleExportStudents = () => {
    if (studentsInSection.length === 0) {
      alert("لا يوجد طلاب مسجلون حالياً للتصدير.");
      return;
    }

    const deptName = DEPARTMENTS.find(d => d.id === selectedDeptId)?.name || '';
