          </div>
        </div>

        <button 
          onClick={onLogout}
          className="flex items-center gap-2 text-rose-600 hover:bg-rose-50 px-4 py-2 rounded-lg transition border border-rose-100"
        >
          <LogOut size={18} />
          تسجيل الخروج
        </button>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8 no-print">
        {/* Sidebar Nav */}
        <aside className="lg:col-span-1 space-y-6">
          <div className="bg-white rounded-2xl shadow-sm p-4 border border-slate-100">
            <h2 className="text-sm font-bold text-slate-400 uppercase tracking-wider mb-4 px-2 border-r-4 border-emerald-500 pr-2">اختيار الفرقة</h2>
            <div className="space-y-2">
              <button 
                onClick={() => setActiveYear('third')}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeYear === 'third' ? 'bg-emerald-700 text-white shadow-lg shadow-emerald-100' : 'hover:bg-slate-50 text-slate-600'}`}
              >
                <GraduationCap size={20} />
