              <button 
                onClick={() => setActiveYear('fourth')}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeYear === 'fourth' ? 'bg-emerald-700 text-white shadow-lg shadow-emerald-100' : 'hover:bg-slate-50 text-slate-600'}`}
              >
