import React, { useState } from 'react';
import { User, Institute, Student, Year } from '../types';
import { DEPARTMENTS } from '../constants';
import { LogOut, GraduationCap, School, FileText, UserPlus, Info, Users, Lock, Trash2, X, Edit2, PlusCircle, Download, Printer } from 'lucide-react';
import LetterGenerator from './LetterGenerator';

interface DashboardProps {
  user: User;
  onLogout: () => void;
  institutes: Institute[];
  students: Student[];
  onRegister: (student: Student) => void;
  onRemoveStudent: (studentId: string, instituteId: string) => void;
  onAddInstitute: (newInst: Omit<Institute, 'id' | 'currentCount'>) => void;
  onUpdateInstitute: (id: string, newName: string) => void;
  onDeleteInstitute: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ 
  user, onLogout, institutes, students, onRegister, onRemoveStudent, 
  onAddInstitute, onUpdateInstitute, onDeleteInstitute 
}) => {
  const [activeYear, setActiveYear] = useState<Year>('third');
  const [selectedDeptId, setSelectedDeptId] = useState<string>(DEPARTMENTS[0].id);
  const [showLetter, setShowLetter] = useState(false);
  const [letterInstituteId, setLetterInstituteId] = useState<string | null>(null);
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);
  const [showSectionReport, setShowSectionReport] = useState(false);

  const filteredInstitutes = institutes.filter(
    inst => inst.year === activeYear && inst.departmentId === selectedDeptId
  );

  const studentsInSection = students.filter(
    s => s.year === activeYear && s.departmentId === selectedDeptId
  ).sort((a, b) => a.name.localeCompare(b.name, 'ar'));

  const getStudentsForInstitute = (instId: string) => {
    return students.filter(s => s.instituteId === instId);
  };

  const handleRegisterClick = (inst: Institute) => {
    if (inst.currentCount >= 6) {
      alert("عذراً، المجموعة مكتملة");
      return;
    }

    const isConfirmed = window.confirm(`هل أنت متأكد من رغبتك في التسجيل بمعهد: (${inst.name})؟\nيرجى العلم أنه لا يمكن تعديل الرغبة بعد الحفظ.`);
    if (!isConfirmed) return;

    const name = prompt("يرجى إدخال اسم الطالب رباعياً:");
    if (name === null) return;

    const nationalId = prompt("يرجى إدخال الرقم القومي للطالب (14 رقم):");
    if (nationalId === null) return;

    if (name.trim() && nationalId.trim()) {
      if (nationalId.length !== 14 || isNaN(Number(nationalId))) {
        alert("خطأ: يجب أن يتكون الرقم القومي من 14 رقماً");
        return;
      }

      const newStudent: Student = {
        id: Math.random().toString(36).substr(2, 9),
        name: name.trim(),
        nationalId: nationalId.trim(),
        year: activeYear,
        departmentId: selectedDeptId,
        instituteId: inst.id
      };
      onRegister(newStudent);
      alert("تم تسجيل الطالب بنجاح.");
    } else {
      alert("خطأ: يرجى ملء كافة البيانات المطلوبة");
    }
  };

  const handleRemoveClick = (student: Student) => {
    const firstConfirm = window.confirm(`هل تود حذف سجل الطالب: ${student.name}؟`);
    if (firstConfirm) {
      const secondConfirm = window.confirm("تنبيه: سيتم إخلاء مكان الطالب في المجموعة. هل أنت متأكد؟");
      if (secondConfirm) {
        onRemoveStudent(student.id, student.instituteId);
        setSelectedStudent(null);
        alert("تم الحذف بنجاح.");
      }
    }
  };

  const handleAddInst = () => {
    const name = prompt("أدخل اسم المعهد الجديد:");
    if (!name) return;
    const location = prompt("أدخل موقع المعهد:");
    if (!location) return;

    onAddInstitute({
      name,
      location,
      maxCapacity: 6,
      departmentId: selectedDeptId,
      year: activeYear
    });
  };

  const handleExportStudents = () => {
    if (studentsInSection.length === 0) {
      alert("لا يوجد طلاب مسجلون حالياً للتصدير.");
      return;
    }

    const deptName = DEPARTMENTS.find(d => d.id === selectedDeptId)?.name || '';
    const yearName = activeYear === 'third' ? 'الفرقة الثالثة' : 'الفرقة الرابعة';

    const headers = ['م', 'الاسم الكامل', 'الالرقم القومي', 'المعهد المسجل به'];
    const rows = studentsInSection.map((s, index) => [
      index + 1,
      s.name,
      `'${s.nationalId}`,
      institutes.find(i => i.id === s.instituteId)?.name || 'غير معروف'
    ]);

    const csvContent = [headers.join(','), ...rows.map(row => row.join(','))].join('\n');
    const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `كشف_طلاب_${deptName}_${yearName}.csv`;
    link.click();
  };

  const handlePrintSection = () => {
    if (studentsInSection.length === 0) {
      alert("لا يوجد طلاب مسجلون في هذه الشعبة للطباعة.");
      return;
    }
    setShowSectionReport(true);
  };

  return (
    <div className="flex-1 container mx-auto px-4 py-8">
      {/* Header */}
      <header className="flex flex-col md:flex-row justify-between items-center mb-10 bg-white p-6 rounded-2xl shadow-sm no-print">
        <div className="flex items-center gap-4 mb-4 md:mb-0">
          <div className="bg-white p-1 rounded-full border-2 border-emerald-100 shadow-sm w-16 h-16 flex items-center justify-center overflow-hidden">
            <img 
              src="https://upload.wikimedia.org/wikipedia/commons/d/d4/Al-Azhar_University_logo.png" 
              alt="اللوجو" 
              className="w-full h-full object-contain"
            />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-slate-800">منصة التربية العملية</h1>
            <p className="text-slate-500">أهلاً بك يا معلم المستقبل، {user.username}</p>
          </div>
        </div>

        <button 
          onClick={onLogout}
          className="flex items-center gap-2 text-rose-600 hover:bg-rose-50 px-4 py-2 rounded-lg transition border border-rose-100"
        >
          <LogOut size={18} />
          تسجيل الخروج
        </button>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8 no-print">
        {/* Sidebar Nav */}
        <aside className="lg:col-span-1 space-y-6">
          <div className="bg-white rounded-2xl shadow-sm p-4 border border-slate-100">
            <h2 className="text-sm font-bold text-slate-400 uppercase tracking-wider mb-4 px-2 border-r-4 border-emerald-500 pr-2">اختيار الفرقة</h2>
            <div className="space-y-2">
              <button 
                onClick={() => setActiveYear('third')}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeYear === 'third' ? 'bg-emerald-700 text-white shadow-lg shadow-emerald-100' : 'hover:bg-slate-50 text-slate-600'}`}
              >
                <GraduationCap size={20} />
                الفرقة الثالثة
              </button>
              <button 
                onClick={() => setActiveYear('fourth')}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeYear === 'fourth' ? 'bg-emerald-700 text-white shadow-lg shadow-emerald-100' : 'hover:bg-slate-50 text-slate-600'}`}
              >
                <GraduationCap size={20} />
                الفرقة الرابعة
              </button>
            </div>
          </div>

          <div className="bg-white rounded-2xl shadow-sm p-4 border border-slate-100">
            <h2 className="text-sm font-bold text-slate-400 uppercase tracking-wider mb-4 px-2 border-r-4 border-emerald-500 pr-2">قائمة الشعب</h2>
            <div className="max-h-[400px] overflow-y-auto space-y-1 pr-1 custom-scrollbar">
              {DEPARTMENTS.map(dept => (
                <button 
                  key={dept.id}
                  onClick={() => setSelectedDeptId(dept.id)}
                  className={`w-full text-right px-4 py-3 rounded-lg text-sm transition-all ${selectedDeptId === dept.id ? 'bg-emerald-50 text-emerald-700 font-bold border-r-4 border-emerald-700' : 'text-slate-600 hover:bg-slate-50'}`}
                >
                  {dept.name}
                </button>
              ))}
            </div>
          </div>
        </aside>

        {/* Main Content Area */}
        <main className="lg:col-span-3">
          <div className="bg-white rounded-2xl shadow-sm overflow-hidden border border-slate-100">
            <div className="p-6 border-b border-slate-100 flex flex-col sm:flex-row justify-between items-center bg-slate-50/50 gap-4">
              <div>
                <h3 className="text-xl font-bold text-slate-800">
                  {activeYear === 'third' ? 'الفرقة الثالثة' : 'الفرقة الرابعة'} - {DEPARTMENTS.find(d => d.id === selectedDeptId)?.name}
                </h3>
                <p className="text-slate-500 text-sm mt-1">إدارة المعاهد والمجموعات (6 طلاب بحد أقصى)</p>
              </div>
              <div className="flex flex-wrap gap-2">
                <button 
                  onClick={handlePrintSection}
                  className="flex items-center gap-2 bg-white text-indigo-700 border border-indigo-200 px-4 py-2 rounded-xl hover:bg-indigo-50 transition shadow-sm font-bold text-sm whitespace-nowrap"
                >
                  <Printer size={18} />
                  طباعة الكشف
                </button>
                <button 
