import React, { useState } from 'react';

interface LoginFormProps {
  onLogin: (username: string, nationalId: string) => void;
}

const LoginForm: React.FC<LoginFormProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [nationalId, setNationalId] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // التحقق من الاسم الرباعي (على الأقل 4 كلمات)
    const nameParts = username.trim().split(/\s+/);
    if (nameParts.length < 4) {
      alert("يرجى إدخال الاسم رباعياً لضمان دقة البيانات");
      return;
    }

    // التحقق من الرقم القومي (14 رقم)
    if (nationalId.length !== 14 || isNaN(Number(nationalId))) {
      alert("خطأ: يجب أن يتكون الرقم القومي من 14 رقماً صحيحاً");
      return;
    }

    onLogin(username, nationalId);
  };

  return (
    <div className="flex-1 flex items-center justify-center p-4">
      <div className="w-full max-w-md bg-white rounded-2xl shadow-2xl overflow-hidden border border-slate-100">
        <div className="bg-emerald-700 p-8 text-center text-white relative">
          <div className="absolute top-0 left-0 w-full h-full opacity-10 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]"></div>
          <div className="relative z-10">
            <div className="w-28 h-28 mx-auto rounded-full bg-white p-2 border-4 border-white/20 mb-4 shadow-lg overflow-hidden flex items-center justify-center">
              <img 
                src="https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Al-Azhar_University_logo.png/512px-Al-Azhar_University_logo.png" 
                alt="شعار جامعة الأزهر" 
                className="w-full h-full object-contain" 
                onError={(e) => {
                  (e.target as HTMLImageElement).src = 'https://alazhar.edu.eg/Portals/0/logo.png';
                }}
              />
            </div>
            <h1 className="text-2xl font-bold">بوابة تسجيل التربية العملية</h1>
            <p className="text-emerald-100 text-sm mt-2 font-medium">كلية التربية بنين بتفهنا الأشراف</p>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6 bg-white">
          <div className="space-y-1">
            <label className="block text-sm font-bold text-slate-700 mr-1 text-right">اسم المستخدم (الاسم رباعياً)</label>
            <input 
              type="text" 
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              className="w-full px-4 py-3 rounded-xl border-2 border-slate-100 focus:border-emerald-500 focus:ring-0 outline-none transition-all text-right text-slate-800 font-semibold"
              placeholder="مثال: محمد أحمد علي حسن"
              required
            />
          </div>

          <div className="space-y-1">
            <label className="block text-sm font-bold text-slate-700 mr-1 text-right">الرقم القومي (14 رقم)</label>
            <input 
              type="text" 
              value={nationalId}
              maxLength={14}
              onChange={(e) => setNationalId(e.target.value.replace(/\D/g, ''))}
              className="w-full px-4 py-3 rounded-xl border-2 border-slate-100 focus:border-emerald-500 focus:ring-0 outline-none transition-all text-center tracking-[0.2em] font-mono text-lg text-slate-700"
              placeholder="20000000000000"
              required
            />
          </div>

          <button 
            type="submit"
            className="w-full bg-emerald-700 hover:bg-emerald-800 text-white font-bold py-4 rounded-xl transition-all transform hover:-translate-y-1 active:scale-95 shadow-xl shadow-emerald-100 flex items-center justify-center gap-2"
          >
            تسجيل الدخول للنظام
          </button>

          <div className="bg-slate-50 p-4 rounded-lg text-center">
            <p className="text-[11px] text-slate-500 leading-relaxed">
              * يتم تخزين بياناتك لضمان سهولة اطلاع القسم على قوائم التوزيع واستخراج خطابات التوجيه.
            </p>
          </div>
        </form>
      </div>
    </div>
  );
};

export default LoginForm;

import React, { useState } from 'react';
import { User, Institute, Student, Year } from '../types';
import { DEPARTMENTS } from '../constants';
import { LogOut, GraduationCap, School, FileText, UserPlus, Info, Users, Lock, Trash2, X, Edit2, PlusCircle, Download, Printer } from 'lucide-react';
import LetterGenerator from './LetterGenerator';

interface DashboardProps {
  user: User;
  onLogout: () => void;
  institutes: Institute[];
  students: Student[];
  onRegister: (student: Student) => void;
  onRemoveStudent: (studentId: string, instituteId: string) => void;
  onAddInstitute: (newInst: Omit<Institute, 'id' | 'currentCount'>) => void;
  onUpdateInstitute: (id: string, newName: string) => void;
  onDeleteInstitute: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ 
  user, onLogout, institutes, students, onRegister, onRemoveStudent, 
  onAddInstitute, onUpdateInstitute, onDeleteInstitute 
}) => {
  const [activeYear, setActiveYear] = useState<Year>('third');
  const [selectedDeptId, setSelectedDeptId] = useState<string>(DEPARTMENTS[0].id);
  const [showLetter, setShowLetter] = useState(false);
  const [letterInstituteId, setLetterInstituteId] = useState<string | null>(null);
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);
  const [showSectionReport, setShowSectionReport] = useState(false);

  const filteredInstitutes = institutes.filter(
    inst => inst.year === activeYear && inst.departmentId === selectedDeptId
  );

  const studentsInSection = students.filter(
    s => s.year === activeYear && s.departmentId === selectedDeptId
  ).sort((a, b) => a.name.localeCompare(b.name, 'ar'));

  const getStudentsForInstitute = (instId: string) => {
    return students.filter(s => s.instituteId === instId);
  };

  const handleRegisterClick = (inst: Institute) => {
    if (inst.currentCount >= 6) {
      alert("عذراً، المجموعة مكتملة");
      return;
    }

    const isConfirmed = window.confirm(`هل أنت متأكد من رغبتك في التسجيل بمعهد: (${inst.name})؟\nيرجى العلم أنه لا يمكن تعديل الرغبة بعد الحفظ.`);
    if (!isConfirmed) return;

    const name = prompt("يرجى إدخال اسم الطالب رباعياً:");
    if (name === null) return;

    const nationalId = prompt("يرجى إدخال الرقم القومي للطالب (14 رقم):");
    if (nationalId === null) return;

    if (name.trim() && nationalId.trim()) {
      if (nationalId.length !== 14 || isNaN(Number(nationalId))) {
        alert("خطأ: يجب أن يتكون الرقم القومي من 14 رقماً");
        return;
      }

      const newStudent: Student = {
        id: Math.random().toString(36).substr(2, 9),
        name: name.trim(),
        nationalId: nationalId.trim(),
        year: activeYear,
        departmentId: selectedDeptId,
        instituteId: inst.id
      };
      onRegister(newStudent);
      alert("تم تسجيل الطالب بنجاح.");
    } else {
      alert("خطأ: يرجى ملء كافة البيانات المطلوبة");
    }
  };

  const handleRemoveClick = (student: Student) => {
    const firstConfirm = window.confirm(`هل تود حذف سجل الطالب: ${student.name}؟`);
    if (firstConfirm) {
      const secondConfirm = window.confirm("تنبيه: سيتم إخلاء مكان الطالب في المجموعة. هل أنت متأكد؟");
      if (secondConfirm) {
        onRemoveStudent(student.id, student.instituteId);
        setSelectedStudent(null);
        alert("تم الحذف بنجاح.");
      }
    }
  };

  const handleAddInst = () => {
    const name = prompt("أدخل اسم المعهد الجديد:");
    if (!name) return;
    const location = prompt("أدخل موقع المعهد:");
    if (!location) return;

    onAddInstitute({
      name,
      location,
      maxCapacity: 6,
      departmentId: selectedDeptId,
      year: activeYear
    });
  };

  const handleExportStudents = () => {
    if (studentsInSection.length === 0) {
      alert("لا يوجد طلاب مسجلون حالياً للتصدير.");
      return;
    }

    const deptName = DEPARTMENTS.find(d => d.id === selectedDeptId)?.name || '';
    const yearName = activeYear === 'third' ? 'الفرقة الثالثة' : 'الفرقة الرابعة';

    const headers = ['م', 'الاسم الكامل', 'الرقم القومي', 'المعهد المسجل به'];
    const rows = studentsInSection.map((s, index) => [
      index + 1,
      s.name,
      `'${s.nationalId}`,
      institutes.find(i => i.id === s.instituteId)?.name || 'غير معروف'
    ]);

    const csvContent = [headers.join(','), ...rows.map(row => row.join(','))].join('\n');
    const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `كشف_طلاب_${deptName}_${yearName}.csv`;
    link.click();
  };

  const handlePrintSection = () => {
    if (studentsInSection.length === 0) {
      alert("لا يوجد طلاب مسجلون في هذه الشعبة للطباعة.");
      return;
    }
    setShowSectionReport(true);
  };

  return (
