      <header className="flex flex-col md:flex-row justify-between items-center mb-10 bg-white p-6 rounded-2xl shadow-sm no-print">
        <div className="flex items-center gap-4 mb-4 md:mb-0">
          <div className="bg-white p-1 rounded-full border-2 border-emerald-100 shadow-sm w-20 h-20 flex items-center justify-center overflow-hidden">
            <img 
              src="https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Al-Azhar_University_logo.png/512px-Al-Azhar_University_logo.png" 
              alt="شعار جامعة الأزهر" 
              className="w-full h-full object-contain p-1"
              onError={(e) => { (e.target as HTMLImageElement).src = 'https://alazhar.edu.eg/Portals/0/logo.png'; }}
            />
          </div>
          <div className="text-right">
            <h1 className="text-2xl font-bold text-slate-800">منصة التربية العملية</h1>
            <p className="text-slate-500">أهلاً بك يا معلم المستقبل، {user.username}</p>
          </div>
        </div>

        <button 
          onClick={onLogout}
          className="flex items-center gap-2 text-rose-600 hover:bg-rose-50 px-4 py-2 rounded-lg transition border border-rose-100"
        >
          <LogOut size={18} />
          تسجيل الخروج
        </button>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8 no-print">
        {/* Sidebar Nav */}
        <aside className="lg:col-span-1 space-y-6">
          <div className="bg-white rounded-2xl shadow-sm p-4 border border-slate-100">
            <h2 className="text-sm font-bold text-slate-400 uppercase tracking-wider mb-4 px-2 border-r-4 border-emerald-500 pr-2 text-right">اختيار الفرقة</h2>
            <div className="space-y-2">
              <button 
                onClick={() => setActiveYear('third')}
                className={`w-full flex items-center justify-between px-4 py-3 rounded-xl transition-all ${activeYear === 'third' ? 'bg-emerald-700 text-white shadow-lg shadow-emerald-100' : 'hover:bg-slate-50 text-slate-600'}`}
              >
                <div className="flex items-center gap-3">
                  <GraduationCap size={20} />
                  <span>الفرقة الثالثة</span>
                </div>
              </button>
              <button 
                onClick={() => setActiveYear('fourth')}
                className={`w-full flex items-center justify-between px-4 py-3 rounded-xl transition-all ${activeYear === 'fourth' ? 'bg-emerald-700 text-white shadow-lg shadow-emerald-100' : 'hover:bg-slate-50 text-slate-600'}`}
              >
                <div className="flex items-center gap-3">
                  <GraduationCap size={20} />
                  <span>الفرقة الرابعة</span>
                </div>
              </button>
            </div>
          </div>

          <div className="bg-white rounded-2xl shadow-sm p-4 border border-slate-100">
            <h2 className="text-sm font-bold text-slate-400 uppercase tracking-wider mb-4 px-2 border-r-4 border-emerald-500 pr-2 text-right">قائمة الشعب</h2>
            <div className="max-h-[500px] overflow-y-auto space-y-2 pr-1 custom-scrollbar">
              {DEPARTMENTS.map(dept => (
                <button 
                  key={dept.id}
                  onClick={() => setSelectedDeptId(dept.id)}
                  className={`w-full text-right px-4 py-4 rounded-xl text-sm transition-all duration-200 ${
                    selectedDeptId === dept.id 
                      ? 'bg-emerald-50 text-emerald-700 font-bold border-r-4 border-emerald-700 shadow-sm ring-1 ring-emerald-100' 
                      : 'text-slate-600 hover:bg-slate-50 hover:pr-5'
                  }`}
                >
                  {dept.name}
                </button>
              ))}
            </div>
          </div>
        </aside>

        {/* Main Content Area */}
        <main className="lg:col-span-3">
          <div className="bg-white rounded-2xl shadow-sm overflow-hidden border border-slate-100">
            <div className="p-6 border-b border-slate-100 flex flex-col sm:flex-row justify-between items-center bg-slate-50/50 gap-4">
              <div className="text-right">
                <h3 className="text-xl font-bold text-slate-800">
                  {activeYear === 'third' ? 'الفرقة الثالثة' : 'الفرقة الرابعة'} - {DEPARTMENTS.find(d => d.id === selectedDeptId)?.name}
                </h3>
                <p className="text-slate-500 text-sm mt-1">إدارة المعاهد والمجموعات (6 طلاب بحد أقصى)</p>
