                          </div>
                        </div>

                        <div className={`${isFull ? 'bg-rose-100/30' : 'bg-slate-50'} rounded-xl p-3 mb-6 border border-slate-100`}>
                          <h5 className={`text-[11px] font-black ${isFull ? 'text-rose-600' : 'text-emerald-600'} uppercase mb-3 flex items-center justify-end gap-1`}>
