                                >
                                  <Info size={14} className={`${isFull ? 'text-rose-200 group-hover:text-rose-400' : 'text-slate-300 group-hover:text-emerald-500'}`} />
                                  <span className={`font-bold ${isFull ? 'text-rose-900 group-hover:text-rose-700' : 'text-slate-700 group-hover:text-emerald-800'}`}>
