import React, { useState, useMemo } from 'react';
import { User, Institute, Student, Year } from '../types';
import { DEPARTMENTS } from '../constants';
import { 
  LogOut, GraduationCap, School, FileText, UserPlus, 
  Info, Users, Lock, Trash2, X, Edit2, PlusCircle, 
  Download, Printer, ChevronDown, ChevronUp, MapPin
} from 'lucide-react';
import LetterGenerator from './LetterGenerator';

interface DashboardProps {
  user: User;
  onLogout: () => void;
  institutes: Institute[];
  students: Student[];
  onRegister: (student: Student) => void;
  onRemoveStudent: (studentId: string, instituteId: string) => void;
  onAddInstitute: (newInst: Omit<Institute, 'id' | 'currentCount'>) => void;
  onUpdateInstitute: (id: string, newName: string) => void;
  onDeleteInstitute: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ 
  user, onLogout, institutes, students, onRegister, onRemoveStudent, 
  onAddInstitute, onUpdateInstitute, onDeleteInstitute 
}) => {
  const [activeYear, setActiveYear] = useState<Year>('third');
  const [selectedDeptId, setSelectedDeptId] = useState<string>(DEPARTMENTS[0].id);
  const [showLetter, setShowLetter] = useState(false);
  const [letterInstituteId, setLetterInstituteId] = useState<string | null>(null);
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);
  const [showSectionReport, setShowSectionReport] = useState(false);
  const [collapsedLocations, setCollapsedLocations] = useState<Record<string, boolean>>({});

  // تصفية المعاهد حسب السنة والشعبة
  const filteredInstitutes = useMemo(() => 
    institutes.filter(inst => inst.year === activeYear && inst.departmentId === selectedDeptId),
    [institutes, activeYear, selectedDeptId]
  );

  // تجميع المعاهد حسب الموقع الجغرافي
  const institutesByLocation = useMemo(() => {
    return filteredInstitutes.reduce((acc, inst) => {
      if (!acc[inst.location]) acc[inst.location] = [];
      acc[inst.location].push(inst);
      return acc;
    }, {} as Record<string, Institute[]>);
  }, [filteredInstitutes]);

  const studentsInSection = students.filter(
    s => s.year === activeYear && s.departmentId === selectedDeptId
  ).sort((a, b) => a.name.localeCompare(b.name, 'ar'));

  const getStudentsForInstitute = (instId: string) => {
    return students.filter(s => s.instituteId === instId);
  };

  const toggleLocationCollapse = (location: string) => {
    setCollapsedLocations(prev => ({ ...prev, [location]: !prev[location] }));
  };

  // Added handlePrintSection function to fix the missing name error
  const handlePrintSection = () => {
    setShowSectionReport(true);
  };

  const handleRegisterClick = (inst: Institute) => {
    if (inst.currentCount >= 6) {
      alert("عذراً، المجموعة مكتملة");
      return;
    }

    const isConfirmed = window.confirm(`هل أنت متأكد من رغبتك في التسجيل بمعهد: (${inst.name})؟\nيرجى العلم أنه لا يمكن تعديل الرغبة بعد الحفظ.`);
    if (!isConfirmed) return;

    const name = prompt("يرجى إدخال اسم الطالب رباعياً:");
    if (name === null) return;

    const nationalId = prompt("يرجى إدخال الرقم القومي للطالب (14 رقم):");
    if (nationalId === null) return;

    if (name.trim() && nationalId.trim()) {
      if (nationalId.length !== 14 || isNaN(Number(nationalId))) {
        alert("خطأ: يجب أن يتكون الرقم القومي من 14 رقماً");
        return;
      }

      const newStudent: Student = {
        id: Math.random().toString(36).substr(2, 9),
        name: name.trim(),
        nationalId: nationalId.trim(),
        year: activeYear,
        departmentId: selectedDeptId,
        instituteId: inst.id
      };
      onRegister(newStudent);
      alert("تم تسجيل الطالب بنجاح.");
    } else {
      alert("خطأ: يرجى ملء كافة البيانات المطلوبة");
    }
  };

  const handleRemoveClick = (student: Student) => {
    if (window.confirm(`هل تود حذف سجل الطالب: ${student.name}؟`)) {
      onRemoveStudent(student.id, student.instituteId);
      setSelectedStudent(null);
    }
  };

  return (
    <div className="flex-1 container mx-auto px-4 py-8 max-w-7xl">
      {/* Header Section */}
      <header className="flex flex-col md:flex-row justify-between items-center mb-8 bg-white p-6 rounded-3xl shadow-sm border border-slate-100 no-print">
        <div className="flex items-center gap-5 mb-4 md:mb-0">
          <div className="bg-white p-1 rounded-2xl border-2 border-emerald-50 shadow-md w-20 h-20 flex items-center justify-center overflow-hidden transition-transform hover:scale-105">
            <img 
              src="https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Al-Azhar_University_logo.png/512px-Al-Azhar_University_logo.png" 
              alt="شعار جامعة الأزهر" 
              className="w-full h-full object-contain p-1"
              onError={(e) => { (e.target as HTMLImageElement).src = 'https://alazhar.edu.eg/Portals/0/logo.png'; }}
            />
          </div>
          <div className="text-right">
            <h1 className="text-2xl font-black text-slate-800 tracking-tight">بوابة التربية العملية الذكية</h1>
            <p className="text-slate-500 font-medium">مرحباً بك، <span className="text-emerald-700 font-bold">{user.username}</span></p>
          </div>
        </div>

        <button 
          onClick={onLogout}
          className="flex items-center gap-2 text-rose-600 bg-rose-50 hover:bg-rose-100 px-6 py-3 rounded-2xl transition-all font-bold border border-rose-100 active:scale-95 group shadow-sm"
        >
          <LogOut size={18} className="group-hover:-translate-x-1 transition-transform" />
          تسجيل الخروج
        </button>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 no-print">
        {/* Modern Sidebar */}
        <aside className="lg:col-span-3 space-y-6">
          {/* Year Switcher (Segmented Control) */}
          <div className="bg-white rounded-3xl shadow-sm p-2 border border-slate-100 flex gap-1">
            <button 
              onClick={() => setActiveYear('third')}
              className={`flex-1 py-3 rounded-2xl font-bold text-sm transition-all flex items-center justify-center gap-2 ${activeYear === 'third' ? 'bg-emerald-700 text-white shadow-lg shadow-emerald-200' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              <GraduationCap size={18} />
              <span>الفرقة الثالثة</span>
            </button>
            <button 
              onClick={() => setActiveYear('fourth')}
              className={`flex-1 py-3 rounded-2xl font-bold text-sm transition-all flex items-center justify-center gap-2 ${activeYear === 'fourth' ? 'bg-emerald-700 text-white shadow-lg shadow-emerald-200' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              <GraduationCap size={18} />
              <span>الفرقة الرابعة</span>
            </button>
          </div>

          {/* Departments List */}
          <div className="bg-white rounded-3xl shadow-sm p-5 border border-slate-100">
            <h2 className="text-xs font-black text-slate-400 uppercase tracking-[0.2em] mb-4 px-2 text-right">اختيار الشعبة الدراسية</h2>
            <div className="space-y-2 max-h-[550px] overflow-y-auto pr-1 custom-scrollbar">
              {DEPARTMENTS.map(dept => (
                <button 
                  key={dept.id}
                  onClick={() => setSelectedDeptId(dept.id)}
                  className={`w-full text-right px-4 py-3.5 rounded-2xl text-sm transition-all duration-300 relative group overflow-hidden ${
                    selectedDeptId === dept.id 
                      ? 'bg-emerald-50 text-emerald-800 font-black border-r-4 border-emerald-700 shadow-sm' 
                      : 'text-slate-600 hover:bg-slate-50 hover:pr-6'
                  }`}
                >
                  <span className="relative z-10">{dept.name}</span>
                  {selectedDeptId === dept.id && (
                    <div className="absolute inset-0 bg-gradient-to-l from-emerald-100/20 to-transparent pointer-events-none"></div>
                  )}
                </button>
              ))}
            </div>
          </div>
        </aside>

        {/* Main Content Area */}
        <main className="lg:col-span-9 space-y-6">
          {/* Quick Actions & Stats Bar */}
          <div className="bg-white rounded-3xl shadow-sm border border-slate-100 p-6 flex flex-col md:flex-row justify-between items-center gap-4">
            <div className="text-right">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2 justify-end">
                <span>{DEPARTMENTS.find(d => d.id === selectedDeptId)?.name}</span>
                <div className="w-2 h-8 bg-emerald-500 rounded-full"></div>
              </h3>
              <p className="text-slate-400 text-xs font-medium mt-1">إجمالي المعاهد النشطة: {filteredInstitutes.length} معاهد</p>
            </div>

            <div className="flex flex-wrap gap-2 justify-center">
              <button 
                onClick={handlePrintSection}
                className="flex items-center gap-2 bg-indigo-50 text-indigo-700 px-5 py-2.5 rounded-2xl hover:bg-indigo-100 transition-all font-bold text-sm border border-indigo-100 active:scale-95"
              >
                <Printer size={18} />
                طباعة الكشف
              </button>
              <button 
                onClick={() => {
                  const name = prompt("اسم المعهد الجديد:");
                  const location = prompt("الموقع:");
                  if (name && location) onAddInstitute({ name, location, maxCapacity: 6, departmentId: selectedDeptId, year: activeYear });
                }}
                className="flex items-center gap-2 bg-emerald-700 text-white px-5 py-2.5 rounded-2xl hover:bg-emerald-800 transition-all font-bold text-sm shadow-lg shadow-emerald-100 active:scale-95"
              >
                <PlusCircle size={18} />
                إضافة معهد
              </button>
            </div>
          </div>

          {/* Grouped Institutes by Location (Collapsible) */}
          <div className="space-y-4">
            {Object.keys(institutesByLocation).length > 0 ? (
              Object.entries(institutesByLocation).map(([location, insts]) => {
                const isCollapsed = collapsedLocations[location];
                // Explicitly cast insts as Institute[] to avoid 'unknown' type errors during mapping
                const institutesForLocation = insts as Institute[];
                return (
                  <section key={location} className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
                    {/* Location Header */}
                    <button 
                      onClick={() => toggleLocationCollapse(location)}
                      className="w-full flex items-center justify-between p-5 hover:bg-slate-50 transition-colors group"
                    >
                      <div className={`transition-transform duration-300 ${isCollapsed ? 'rotate-180' : ''}`}>
                        <ChevronDown size={20} className="text-slate-400" />
                      </div>
                      <div className="flex items-center gap-3">
                        <span className="text-xs font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full">{institutesForLocation.length} معاهد</span>
                        <h3 className="text-lg font-bold text-slate-700 flex items-center gap-2">
                          {location}
                          <MapPin size={18} className="text-emerald-500" />
                        </h3>
                      </div>
                    </button>

                    {/* Institutes Grid inside Location */}
                    {!isCollapsed && (
                      <div className="p-5 pt-0 grid grid-cols-1 xl:grid-cols-2 gap-4 animate-in slide-in-from-top-2 duration-300">
                        {institutesForLocation.map(inst => {
                          const isFull = inst.currentCount >= inst.maxCapacity;
                          const instStudents = getStudentsForInstitute(inst.id);
                          return (
                            <div 
                              key={inst.id} 
                              className={`group relative border-2 rounded-2xl p-5 transition-all flex flex-col ${isFull ? 'bg-rose-50/10 border-rose-100' : 'bg-white border-slate-100 hover:border-emerald-200 hover:shadow-md'}`}
                            >
                              <div className="flex justify-between items-start mb-4">
                                <div className="flex gap-2">
                                  <button onClick={() => {
                                    if (window.confirm("حذف المعهد؟")) onDeleteInstitute(inst.id);
                                  }} className="p-2 text-rose-300 hover:text-rose-600 hover:bg-rose-50 rounded-xl transition-colors">
                                    <Trash2 size={16} />
                                  </button>
                                  <button onClick={() => {
                                    const n = prompt("تعديل الاسم:", inst.name);
                                    if (n) onUpdateInstitute(inst.id, n);
                                  }} className="p-2 text-slate-300 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-colors">
                                    <Edit2 size={16} />
                                  </button>
                                </div>
                                <div className="text-right">
                                  <h4 className="font-bold text-slate-800">{inst.name}</h4>
                                  <span className={`text-[10px] font-black uppercase tracking-wider ${isFull ? 'text-rose-600' : 'text-emerald-600'}`}>
                                    {isFull ? 'مكتمل' : 'متاح للتسجيل'}
                                  </span>
                                </div>
                              </div>

                              {/* Progress Bar */}
                              <div className="mb-4">
                                <div className="flex justify-between text-[10px] font-bold mb-1">
                                  <span className="text-slate-400">السعة: 6 طلاب</span>
                                  <span className={isFull ? 'text-rose-600' : 'text-emerald-600'}>{inst.currentCount} / 6</span>
                                </div>
                                <div className="w-full bg-slate-100 h-2 rounded-full overflow-hidden border border-slate-50">
                                  <div 
                                    className={`h-full transition-all duration-700 ${isFull ? 'bg-rose-500' : 'bg-emerald-500'}`}
                                    style={{ width: `${(inst.currentCount / 6) * 100}%` }}
                                  ></div>
                                </div>
                              </div>

                              {/* Student List Preview */}
                              <div className="flex-1 space-y-2 mb-4">
                                {instStudents.length > 0 ? (
                                  instStudents.map((s, i) => (
                                    <div 
                                      key={s.id} 
                                      onClick={() => setSelectedStudent(s)}
                                      className="flex items-center justify-between text-[11px] bg-slate-50 hover:bg-white p-2 rounded-xl border border-transparent hover:border-emerald-100 cursor-pointer transition-all"
                                    >
                                      <Info size={12} className="text-slate-300" />
                                      <span className="font-bold text-slate-600">{i+1}. {s.name.split(' ')[0]} {s.name.split(' ')[1]}...</span>
                                    </div>
                                  ))
                                ) : (
                                  <div className="py-4 text-center text-slate-300 text-[10px] italic border border-dashed rounded-xl">لا يوجد مسجلين</div>
                                )}
                              </div>

                              {/* Action Buttons */}
                              <div className="flex gap-2">
                                <button 
                                  onClick={() => { setLetterInstituteId(inst.id); setShowLetter(true); }}
                                  disabled={inst.currentCount === 0}
                                  className={`flex-1 flex items-center justify-center gap-1.5 py-2 rounded-xl text-xs font-black transition-all border-2 ${inst.currentCount > 0 ? 'border-emerald-700 text-emerald-700 hover:bg-emerald-50' : 'border-slate-100 text-slate-200 cursor-not-allowed opacity-50'}`}
                                >
                                  <FileText size={14} /> الخطاب
                                </button>
                                {!isFull && (
                                  <button 
                                    onClick={() => handleRegisterClick(inst)}
                                    className="flex-1 flex items-center justify-center gap-1.5 bg-emerald-700 text-white py-2 rounded-xl text-xs font-black hover:bg-emerald-800 transition-all shadow-md active:scale-95"
                                  >
                                    <UserPlus size={14} /> تسجيل
                                  </button>
                                )}
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    )}
                  </section>
                );
              })
            ) : (
              <div className="py-32 text-center bg-white rounded-3xl border border-slate-100 shadow-sm">
                <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-6">
                  <School size={40} className="text-slate-200" />
                </div>
                <h3 className="text-xl font-black text-slate-800">لا توجد معاهد متاحة</h3>
                <p className="text-slate-400 mt-2">يرجى إضافة معاهد لهذه الشعبة أو اختيار شعبة أخرى</p>
              </div>
            )}
          </div>
        </main>
      </div>

      {/* Student Details Overlay */}
      {selectedStudent && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/40 p-4 backdrop-blur-md no-print">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in duration-200">
            <div className="p-8 text-right space-y-8">
              <div className="flex justify-between items-center">
                <button onClick={() => setSelectedStudent(null)} className="p-3 bg-slate-100 hover:bg-slate-200 rounded-2xl transition-all active:scale-90">
                  <X size={20} className="text-slate-500" />
                </button>
                <h3 className="text-2xl font-black text-slate-800">بيانات الطالب</h3>
              </div>

              <div className="space-y-6">
                <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100">
                  <div className="mb-4">
                    <label className="text-[10px] font-black text-emerald-600 uppercase mb-1 block">الاسم الرباعي</label>
                    <p className="text-xl font-bold text-slate-800 leading-tight">{selectedStudent.name}</p>
                  </div>
                  <div className="mb-4">
                    <label className="text-[10px] font-black text-emerald-600 uppercase mb-1 block">الرقم القومي</label>
                    <p className="text-xl font-bold text-slate-600 font-mono tracking-widest">{selectedStudent.nationalId}</p>
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-emerald-600 uppercase mb-1 block">المعهد الحالي</label>
                    <p className="text-lg font-bold text-slate-700">{institutes.find(i => i.id === selectedStudent.instituteId)?.name}</p>
                  </div>
                </div>

                <button 
                  onClick={() => handleRemoveClick(selectedStudent)}
                  className="w-full py-5 bg-rose-50 text-rose-600 hover:bg-rose-600 hover:text-white rounded-[1.5rem] font-black transition-all shadow-sm active:scale-95 flex items-center justify-center gap-3"
                >
                  <Trash2 size={20} />
                  حذف السجل نهائياً
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Printing Reports Modals */}
      {showSectionReport && (
        <SectionReportModal 
          activeYear={activeYear}
          selectedDeptId={selectedDeptId}
          studentsInSection={studentsInSection}
          institutes={institutes}
          onClose={() => setShowSectionReport(false)}
        />
      )}

      {showLetter && letterInstituteId && (
        <LetterGenerator 
          institute={institutes.find(i => i.id === letterInstituteId)!}
          students={getStudentsForInstitute(letterInstituteId)}
          onClose={() => setShowLetter(false)}
        />
      )}
    </div>
  );
};

// Internal sub-component for report rendering to keep Dashboard clean
const SectionReportModal: React.FC<{
  activeYear: Year;
  selectedDeptId: string;
  studentsInSection: Student[];
  institutes: Institute[];
  onClose: () => void;
}> = ({ activeYear, selectedDeptId, studentsInSection, institutes, onClose }) => (
  <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/60 p-4 no-print-backdrop">
    <div className="bg-white w-full max-w-5xl max-h-[95vh] rounded-[2rem] shadow-2xl flex flex-col overflow-hidden">
      <div className="p-6 border-b flex justify-between items-center bg-slate-50 no-print">
        <div className="flex gap-3">
          <button onClick={() => window.print()} className="bg-indigo-700 text-white px-8 py-3 rounded-2xl font-black shadow-lg hover:bg-indigo-800 transition-all active:scale-95">بدء الطباعة</button>
          <button onClick={onClose} className="p-3 bg-white border border-slate-200 text-slate-400 hover:bg-slate-100 rounded-2xl transition-all active:scale-95"><X size={24} /></button>
        </div>
        <h3 className="font-black text-slate-800 text-lg">تقرير توزيع الشعبة</h3>
      </div>
      <div className="flex-1 overflow-y-auto p-12 bg-white print:p-0">
        <div className="w-full mx-auto print:p-8" style={{ direction: 'rtl' }}>
          <div className="text-center mb-10 border-b-4 border-slate-900 pb-8">
            <h1 className="text-3xl font-black mb-2">جامعة الأزهر - كلية التربية بنين بتفهنا الأشراف</h1>
            <h2 className="text-xl font-bold text-slate-600">كشف بأسماء طلاب التربية العملية</h2>
            <div className="flex justify-center gap-10 mt-6 text-sm font-bold bg-slate-100 p-4 rounded-3xl inline-flex shadow-inner">
              <span>الفرقة: {activeYear === 'third' ? 'الثالثة' : 'الرابعة'}</span>
              <span className="w-1.5 h-1.5 bg-slate-300 rounded-full my-auto"></span>
              <span>الشعبة: {DEPARTMENTS.find(d => d.id === selectedDeptId)?.name}</span>
              <span className="w-1.5 h-1.5 bg-slate-300 rounded-full my-auto"></span>
              <span>المسجلين: {studentsInSection.length}</span>
            </div>
          </div>
          <table className="w-full border-collapse border-4 border-slate-900 text-right">
            <thead>
              <tr className="bg-slate-900 text-white">
                <th className="border-2 border-slate-900 p-4 w-16 text-center">م</th>
                <th className="border-2 border-slate-900 p-4">اسم الطالب رباعياً</th>
                <th className="border-2 border-slate-900 p-4 w-64 text-center">الرقم القومي</th>
                <th className="border-2 border-slate-900 p-4">المعهد الموزع عليه</th>
              </tr>
            </thead>
            <tbody>
              {studentsInSection.map((s, i) => (
                <tr key={s.id} className={i % 2 === 0 ? 'bg-white' : 'bg-slate-50'}>
                  <td className="border-2 border-slate-900 p-4 text-center font-black">{i + 1}</td>
                  <td className="border-2 border-slate-900 p-4 font-bold text-slate-800">{s.name}</td>
                  <td className="border-2 border-slate-900 p-4 text-center font-mono tracking-tighter">{s.nationalId}</td>
                  <td className="border-2 border-slate-900 p-4 font-medium">{institutes.find(inst => inst.id === s.instituteId)?.name}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  </div>
);

export default Dashboard;

import React from 'react';
import { GraduationCap, ArrowLeft, Sparkles } from 'lucide-react';

interface WelcomeOverlayProps {
  username: string;
  onDismiss: () => void;
}

const WelcomeOverlay: React.FC<WelcomeOverlayProps> = ({ username, onDismiss }) => {
  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center bg-white/95 backdrop-blur-md animate-in fade-in duration-500">
