        {/* Main Tabs Content */}
        <main className={`${activeTab === 'contact' ? 'lg:col-span-12' : 'lg:col-span-9'} space-y-6`}>

          {/* Tab 1: Site Management */}
          {activeTab === 'management' && (
            <div className="space-y-6 animate-in slide-in-from-left-4 duration-500">
