                    {!collapsedLocations[location] && (
                      <div className="p-5 pt-0 grid grid-cols-1 md:grid-cols-2 gap-4">
                        {insts.map(inst => {
                          const isFull = inst.currentCount >= inst.maxCapacity;
                          return (
