                                <div className="flex gap-1">
                                  <button 
                                    onClick={() => {setLetterInstituteId(inst.id); setShowLetter(true);}}
                                    disabled={inst.currentCount === 0}
                                    className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-lg disabled:opacity-30"
                                  >
                                    <FileText size={16} />
                                  </button>
                                  {!isFull && (
                                    <button 
                                      onClick={() => handleRegisterClick(inst)}
                                      className="bg-emerald-700 text-white px-3 py-1.5 rounded-xl text-[10px] font-black hover:bg-emerald-800 transition-all"
                                    >
                                      تسجيل
                                    </button>
                                  )}
                                </div>
                              </div>
                            </div>
                          )
                        })}
                      </div>
                    )}
