          >
            <UserPlus size={18} />
            تسجيل الطلاب
          </button>
          <button 
            onClick={() => setActiveTab('management')}
            className={`flex-1 flex items-center justify-center gap-2 py-4 rounded-3xl font-black text-sm transition-all ${activeTab === 'management' ? 'bg-indigo-700 text-white shadow-lg shadow-indigo-200 scale-105' : 'text-slate-500 hover:bg-slate-50'}`}
          >
