                <p className="text-emerald-100 text-xs font-black uppercase tracking-widest">جامعة الأزهر الشريف</p>
                <div className="h-[1.5px] w-10 bg-gradient-to-r from-amber-400/80 to-transparent"></div>
              </div>
              <p className="text-amber-200/80 text-[10px] font-bold mt-1 uppercase tracking-tighter">كلية التربية بتفهنا الأشراف</p>
            </div>
          </div>

          {/* Form Section */}
          <form onSubmit={handleSubmit} className="p-10 space-y-7 bg-white">
            <div className="space-y-2">
              <label className="block text-xs font-black text-slate-400 mr-2 text-right uppercase tracking-widest">اسم المستخدم (الاسم رباعياً)</label>
              <input 
                type="text" 
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                className="w-full px-5 py-4 rounded-2xl border-2 border-slate-50 bg-slate-50 focus:bg-white focus:border-emerald-500 focus:ring-4 focus:ring-emerald-50 outline-none transition-all text-right text-slate-800 font-bold placeholder:text-slate-300"
                placeholder="أدخل اسمك كما في الكشف"
                required
