                (e.target as HTMLImageElement).src = 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Al-Azhar_University_logo.png/512px-Al-Azhar_University_logo.png';
              }}
            />
          </div>
          <div className="text-right">
            <h1 className="text-2xl font-black text-slate-800 tracking-tight">بوابة التربية العملية</h1>
            <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">{DEPARTMENTS.find(d => d.id === selectedDeptId)?.name}</p>
          </div>
        </div>

        <div className="flex items-center gap-4 mt-4 md:mt-0">
