                                    style={{ width: `${percentage}%` }}
                                  >
                                    {percentage > 15 && (
                                      <span className="text-[9px] font-black text-white bg-black/20 px-1.5 py-0.5 rounded-md backdrop-blur-sm">
                                        {percentage}%
