                                  </div>
                                )}
                              </div>
                            </div>
                          )
                        })}
                      </div>
                    )}
                  </section>
                ))}
              </div>
            </div>
          )}

          {activeTab === 'management' && (
            <div className="animate-in slide-in-from-right-6 duration-500 space-y-6">
              {!isAdminAuthorized ? (
