                      autoFocus
                    />
                    <button type="submit" className="w-full bg-indigo-700 text-white py-4 rounded-2xl font-black text-lg hover:bg-indigo-800 transition-all shadow-xl shadow-indigo-100 active:scale-95">تأكيد الهوية</button>
                  </form>
