                        className="bg-indigo-700 text-white flex items-center gap-3 px-8 py-4 rounded-2xl font-black text-sm hover:bg-indigo-800 transition-all shadow-xl active:scale-95"
                      >
                        <PlusCircle size={22} /> إضافة معهد جديد
