                  <div className={`p-4 rounded-2xl text-sm font-bold leading-relaxed ${msg.role === 'user' ? 'bg-[#055039] text-white rounded-tr-none' : 'bg-white text-slate-800 rounded-tl-none border border-slate-200'}`}>
